PathwayData.put("data/reading_writing/units/L01U6.json",{"strand":"reading_writing","level":1,"cefr":"A1a","unit":6,"theme":"Weather and Seasons","essential_question":"How does the weather change what we do?","schema_version":"1.0","core_words":["sun","rain","wind","cloud","hot","cold","sunny","rainy","windy","summer","winter","umbrella","coat","sky"],"recycled_words":["happy","friend","grandfather","garden","play","open","family","hot","cold","favorite","different","ready"],"rubrics":[{"id":"RW-RUBRIC-5T","title":"Analytic writing rubric","traits":[{"name":"Ideas","name_ar":"الأفكار","bands":[{"score":4,"descriptor":"My ideas are clear, interesting and fully developed with strong details.","descriptor_ar":"أفكاري واضحة وممتعة ومدعومة بتفاصيل قوية."},{"score":3,"descriptor":"My ideas are clear and have enough details.","descriptor_ar":"أفكاري واضحة ومعها تفاصيل كافية."},{"score":2,"descriptor":"My main idea is there but needs more details.","descriptor_ar":"فكرتي الرئيسية موجودة لكنها تحتاج إلى تفاصيل أكثر."},{"score":1,"descriptor":"My ideas are unclear or very few.","descriptor_ar":"أفكاري غير واضحة أو قليلة جدًا."}]},{"name":"Organization","name_ar":"التنظيم","bands":[{"score":4,"descriptor":"Clear beginning, middle and end; ideas flow with linking words.","descriptor_ar":"بداية ووسط ونهاية واضحة، والأفكار مترابطة بكلمات الربط."},{"score":3,"descriptor":"Clear order with some linking words.","descriptor_ar":"ترتيب واضح مع بعض كلمات الربط."},{"score":2,"descriptor":"Some order, but parts are mixed up.","descriptor_ar":"يوجد بعض الترتيب لكن بعض الأجزاء غير مرتبة."},{"score":1,"descriptor":"Ideas are not in order.","descriptor_ar":"الأفكار غير مرتبة."}]},{"name":"Vocabulary","name_ar":"المفردات","bands":[{"score":4,"descriptor":"I use exact, varied words, including new unit words, correctly.","descriptor_ar":"أستخدم كلمات دقيقة ومتنوعة، منها كلمات الوحدة الجديدة، بشكل صحيح."},{"score":3,"descriptor":"I use some new words correctly.","descriptor_ar":"أستخدم بعض الكلمات الجديدة بشكل صحيح."},{"score":2,"descriptor":"I use simple words; some are repeated or wrong.","descriptor_ar":"أستخدم كلمات بسيطة، وبعضها مكرر أو غير صحيح."},{"score":1,"descriptor":"I use very few words; the meaning is hard to understand.","descriptor_ar":"أستخدم كلمات قليلة جدًا ويصعب فهم المعنى."}]},{"name":"Sentence fluency","name_ar":"سلاسة الجمل","bands":[{"score":4,"descriptor":"My sentences are complete, varied in length and easy to read aloud.","descriptor_ar":"جملي كاملة ومتنوعة الطول وسهلة القراءة بصوت عالٍ."},{"score":3,"descriptor":"Most sentences are complete, with some variety.","descriptor_ar":"معظم جملي كاملة مع بعض التنويع."},{"score":2,"descriptor":"Many sentences are short or start the same way.","descriptor_ar":"كثير من جملي قصيرة أو تبدأ بالطريقة نفسها."},{"score":1,"descriptor":"Sentences are incomplete or run together.","descriptor_ar":"جملي ناقصة أو متداخلة."}]},{"name":"Conventions","name_ar":"قواعد الكتابة","bands":[{"score":4,"descriptor":"Capitals, punctuation, spelling and grammar are almost always correct.","descriptor_ar":"الحروف الكبيرة وعلامات الترقيم والإملاء والقواعد صحيحة دائمًا تقريبًا."},{"score":3,"descriptor":"A few mistakes that do not affect meaning.","descriptor_ar":"أخطاء قليلة لا تؤثر في المعنى."},{"score":2,"descriptor":"Several mistakes; the meaning is sometimes unclear.","descriptor_ar":"عدة أخطاء، والمعنى أحيانًا غير واضح."},{"score":1,"descriptor":"Many mistakes make it hard to read.","descriptor_ar":"أخطاء كثيرة تجعل القراءة صعبة."}]}]}],"lessons":[{"id":"RW-L01-U6-LS1","title":"Word Power: Weather and Seasons","lesson_type":"vocabulary","objectives":["read and say 14 weather words and 2 Tier 2 words (weather, season)","use picture clues and sentence clues to work out the meaning of weather words","describe today's weather and say what they wear and do"],"objectives_ar":["قراءة ونطق 14 كلمة عن الطقس وكلمتين أكاديميتين (weather, season).","استخدام أدلة الصورة والجملة لمعرفة معاني كلمات الطقس.","وصف طقس اليوم وما يلبسونه ويفعلونه."],"success_criteria":["I can read and say the weather words.","I can use the picture and the sentence to find a word's meaning.","I can say what the weather is like today."],"success_criteria_ar":["أستطيع قراءة كلمات الطقس ونطقها.","أستطيع استخدام الصورة والجملة لمعرفة معنى الكلمة.","أستطيع قول كيف هو الطقس اليوم."],"map_area":"Vocabulary: Acquisition and Use","vocabulary":[{"word":"sun","pos":"noun","ipa":"/sʌn/","definition":"the big bright star in the sky in the day","arabic":"شمس","example":"The sun is very bright.","image_id":"IMG-RW-L01-U6-LS1-V01","audio_id":"AUD-RW-L01-U6-LS1-V01","tier":"core"},{"word":"rain","pos":"noun","ipa":"/reɪn/","definition":"water that falls from clouds","arabic":"مطر","example":"The rain falls on the roof.","image_id":"IMG-RW-L01-U6-LS1-V02","audio_id":"AUD-RW-L01-U6-LS1-V02","tier":"core"},{"word":"wind","pos":"noun","ipa":"/wɪnd/","definition":"moving air","arabic":"رياح","example":"The wind moves the palm trees.","image_id":"IMG-RW-L01-U6-LS1-V03","audio_id":"AUD-RW-L01-U6-LS1-V03","tier":"core"},{"word":"cloud","pos":"noun","ipa":"/klaʊd/","definition":"a white or gray shape in the sky","arabic":"سحابة","example":"A big cloud covers the sun.","image_id":"IMG-RW-L01-U6-LS1-V04","audio_id":"AUD-RW-L01-U6-LS1-V04","tier":"core"},{"word":"hot","pos":"adjective","ipa":"/hɑt/","definition":"very warm","arabic":"حار","example":"It is hot in summer.","image_id":"IMG-RW-L01-U6-LS1-V05","audio_id":"AUD-RW-L01-U6-LS1-V05","tier":"core"},{"word":"cold","pos":"adjective","ipa":"/koʊld/","definition":"not warm","arabic":"بارد","example":"The water is cold.","image_id":"IMG-RW-L01-U6-LS1-V06","audio_id":"AUD-RW-L01-U6-LS1-V06","tier":"core"},{"word":"sunny","pos":"adjective","ipa":"/ˈsʌni/","definition":"with a lot of sun","arabic":"مشمس","example":"It is a sunny day.","image_id":"IMG-RW-L01-U6-LS1-V07","audio_id":"AUD-RW-L01-U6-LS1-V07","tier":"core"},{"word":"rainy","pos":"adjective","ipa":"/ˈreɪni/","definition":"with a lot of rain","arabic":"ممطر","example":"It is a rainy morning.","image_id":"IMG-RW-L01-U6-LS1-V08","audio_id":"AUD-RW-L01-U6-LS1-V08","tier":"core"},{"word":"windy","pos":"adjective","ipa":"/ˈwɪndi/","definition":"with a lot of wind","arabic":"عاصف / كثير الرياح","example":"It is windy today.","image_id":"IMG-RW-L01-U6-LS1-V09","audio_id":"AUD-RW-L01-U6-LS1-V09","tier":"core"},{"word":"summer","pos":"noun","ipa":"/ˈsʌmər/","definition":"the hottest season of the year","arabic":"الصيف","example":"We swim in summer.","image_id":"IMG-RW-L01-U6-LS1-V10","audio_id":"AUD-RW-L01-U6-LS1-V10","tier":"core"},{"word":"winter","pos":"noun","ipa":"/ˈwɪntər/","definition":"the coldest season of the year","arabic":"الشتاء","example":"It rains in winter.","image_id":"IMG-RW-L01-U6-LS1-V11","audio_id":"AUD-RW-L01-U6-LS1-V11","tier":"core"},{"word":"umbrella","pos":"noun","ipa":"/ʌmˈbrɛlə/","definition":"you hold it over your head in the rain","arabic":"مظلة","example":"Take your umbrella!","image_id":"IMG-RW-L01-U6-LS1-V12","audio_id":"AUD-RW-L01-U6-LS1-V12","tier":"core"},{"word":"coat","pos":"noun","ipa":"/koʊt/","definition":"warm clothes you wear over other clothes","arabic":"معطف","example":"Put on your coat.","image_id":"IMG-RW-L01-U6-LS1-V13","audio_id":"AUD-RW-L01-U6-LS1-V13","tier":"core"},{"word":"sky","pos":"noun","ipa":"/skaɪ/","definition":"the space above the land","arabic":"سماء","example":"The sky is gray today.","image_id":"IMG-RW-L01-U6-LS1-V14","audio_id":"AUD-RW-L01-U6-LS1-V14","tier":"core"},{"word":"weather","pos":"noun","ipa":"/ˈwɛðər/","definition":"how the sky and air are: sunny, rainy, windy, hot or cold","arabic":"الطقس","example":"What is the weather like?","image_id":"IMG-RW-L01-U6-LS1-V15","audio_id":"AUD-RW-L01-U6-LS1-V15","tier":"tier2"},{"word":"season","pos":"noun","ipa":"/ˈsizən/","definition":"a part of the year, like summer or winter","arabic":"فصل (من فصول السنة)","example":"Winter is my favorite season.","image_id":"IMG-RW-L01-U6-LS1-V16","audio_id":"AUD-RW-L01-U6-LS1-V16","tier":"tier2"}],"explanation":{"text":"Sometimes a new word has a **picture**. Look at it first: it is a **picture clue**.\n\nOther words in the **sentence** can help too. They are **sentence clues**. *Take your umbrella! It is rainy.* → rain + take = something for the rain.\n\nUse both: **look** at the picture, **read** the sentence, **guess** the meaning, **check** with a friend or the glossary.\n\nWeather words often come in pairs: **sun → sunny**, **rain → rainy**, **wind → windy**. Add **-y** to describe the day!","examples":["Picture: a bright yellow circle. Sentence: *The **sun** is hot.* → the sun is the bright star in the sky.","Picture: drops of water. Sentence: *The **rain** falls on the roof.* → rain is water from clouds.","Sentence clue: *The wind is strong. It is **windy**.* → windy = with a lot of wind.","Sentence clue: *It is cold, so I put on my **coat**.* → a coat is warm clothes.","Sentence clue: *Open your **umbrella**. The rain is heavy!* → an umbrella keeps rain off.","Picture: a gray shape covering the sun. Sentence: *A big **cloud** covers the sun.*","Sentence clue: *In **summer**, it is very hot. We swim.* → summer is the hot season.","Sentence clue: *In **winter**, it is cold and it rains.* → winter is the cold season.","sun → sunny · rain → rainy · wind → windy · cloud → cloudy"],"common_errors":["✗ Today is sun. → ✓ Today is sunny. / It is sunny today. (Use **sunny** (with -y) to describe the day.)","✗ It is rain today. → ✓ It is rainy today. / It is raining. (Use **rainy** to describe the day.)","✗ The weather is very hotly. → ✓ The weather is very hot. (Say **hot**.)","✗ I wear my coat in the summer hot. → ✓ I wear my coat in winter. (Coats are for cold weather.)","✗ In the winter is cold. → ✓ In winter, it is cold. (English needs **it**: it is cold.)","✗ open umbrella → ✓ Open your umbrella. (Add **your** and a period.)","✗ The wether is nice. → ✓ The weather is nice. (Spelling: w-e-**a**-t-h-e-r.)"],"arabic":"أحيانًا تأتي الكلمة الجديدة مع صورة، فانظر إليها أولًا: إنها دليل الصورة.\n\nوالكلمات الأخرى في الجملة تساعدك أيضًا: إنها أدلة الجملة. انظر، اقرأ، خمّن المعنى، ثم تحقق.\n\nكلمات الطقس تأتي في أزواج: sun ← sunny، rain ← rainy، wind ← windy. أضف y لتصف اليوم!\n\nانتبه: في الإنجليزية نقول It is cold ولا نحذف it كما في العربية \"الجو بارد\"."},"video":{"script":[{"time":"00:00–00:15","narration":"What is the weather like today? Let's look at the sky!","on_screen":"Weather and Seasons","visual":"Saqr flies through four quick skies: sunny, cloudy, rainy, windy."},{"time":"00:15–00:45","narration":"The sun! It is sunny. The rain! It is rainy. The wind! It is windy.","on_screen":"sun → sunny · rain → rainy · wind → windy","visual":"Each noun card grows a '-y' tail and turns into the describing word."},{"time":"00:45–01:15","narration":"Look at the cloud. It is gray. A cloud can bring rain.","on_screen":"cloud · sky","visual":"A gray cloud drifts over a blue sky and drops rain."},{"time":"01:15–01:45","narration":"It is cold. Put on your coat! It is rainy. Open your umbrella!","on_screen":"coat · umbrella","visual":"Sami puts on a coat; Lama opens a red umbrella."},{"time":"01:45–02:10","narration":"In Saudi Arabia, summer is very hot. Winter is cool and sometimes rainy.","on_screen":"summer ☀️ · winter 🌧️","visual":"A circle turns from a hot summer beach to a cool winter day in Taif."},{"time":"02:10–02:30","narration":"Use the picture and the sentence to find what words mean. Weather detective!","on_screen":"Picture + sentence = meaning","visual":"Saqr holds a magnifying glass over a sentence and a picture."}],"captions_ar":["كيف هو الطقس اليوم؟ لننظر إلى السماء!","الشمس: الجو مشمس. المطر: الجو ممطر. الرياح: الجو عاصف.","انظروا إلى السحابة. إنها رمادية. السحابة قد تجلب المطر.","الجو بارد، البس معطفك! الجو ممطر، افتح مظلتك!","في السعودية الصيف حار جدًا، والشتاء معتدل البرودة وأحيانًا ممطر.","استخدم الصورة والجملة لتعرف معاني الكلمات. أنت محقق الطقس!"],"voice":"Narrator: American English, warm female teacher, speed 0.8, like a friendly weather reporter. Saqr: playful. Light weather sound effects."},"texts":[],"activities":[{"id":"RW-L01-U6-LS1-A1","type":"mcq","stage":"controlled","instructions":"Controlled practice: Use the picture or sentence clue. Choose the word.","instructions_ar":"استخدم دليل الصورة أو الجملة واختر الكلمة.","items":[{"q":"Water falls from the clouds. It is ___.","answer":"rain","explanation":"Water from clouds is rain.","explanation_ar":"الماء من السحب مطر.","options":["rain","sun","wind","coat"],"dok":1,"skill":"sentence clue","stage":"controlled"},{"q":"Picture: a kite flying high and a hat blowing away. It is ___.","answer":"windy","explanation":"Moving air = windy.","explanation_ar":"رياح.","options":["windy","sunny","rainy","hot"],"dok":1,"skill":"picture clue","stage":"controlled"},{"q":"The bright star in the sky in the day is the ___.","answer":"sun","explanation":"The sun is the bright star.","explanation_ar":"الشمس.","options":["cloud","rain","coat","sun"],"dok":1,"skill":"vocabulary","stage":"controlled"},{"q":"It is cold, so I put on my ___.","answer":"coat","explanation":"A coat keeps you warm.","explanation_ar":"المعطف للدفء.","options":["umbrella","sun","cloud","coat"],"dok":1,"skill":"sentence clue","stage":"controlled"},{"q":"The hottest season of the year is ___.","answer":"summer","explanation":"Summer is the hottest.","explanation_ar":"الصيف.","options":["winter","summer","rainy","cloud"],"dok":1,"skill":"vocabulary","stage":"controlled"},{"q":"A gray shape in the sky that can bring rain is a ___.","answer":"cloud","explanation":"Clouds bring rain.","explanation_ar":"السحابة.","options":["coat","season","cloud","sun"],"dok":1,"skill":"vocabulary","stage":"controlled"}]},{"id":"RW-L01-U6-LS1-A2","type":"gap_fill","stage":"guided","instructions":"Guided practice: Complete with a word from the bank.","instructions_ar":"أكمل بكلمة من البنك.","items":[{"q":"Take your ________. It is rainy!","answer":"umbrella","explanation":"Umbrellas keep the rain off.","explanation_ar":"المظلة.","stage":"guided"},{"q":"The ________ is blue and there are no clouds.","answer":"sky","explanation":"The sky is above us.","explanation_ar":"السماء.","stage":"guided"},{"q":"It is very ________ in summer. Drink water!","answer":"hot","explanation":"Summer is hot.","explanation_ar":"حار.","stage":"guided"},{"q":"In ________, it is cool and sometimes it rains.","answer":"winter","explanation":"Winter is cooler.","explanation_ar":"الشتاء.","stage":"guided"},{"q":"What is the ________ like today? It is sunny.","answer":"weather","explanation":"Weather = how the sky and air are.","explanation_ar":"الطقس.","stage":"guided"},{"q":"My favorite ________ is winter.","answer":"season","explanation":"Winter is a season.","explanation_ar":"فصل.","stage":"guided"}]},{"id":"RW-L01-U6-LS1-A3","type":"open","stage":"freer","instructions":"Freer practice: Make the -y word. Then write a sentence.","instructions_ar":"كوّن كلمة بـ y ثم اكتب جملة.","items":[{"q":"rain + y = ______. Write: It is ______ today.","answer":"rainy – It is rainy today.","explanation":"rain + y.","explanation_ar":"rain + y.","dok":1,"skill":"word families","stage":"freer"},{"q":"wind + y = ______. Write a sentence.","answer":"windy – It is windy in Abha.","explanation":"wind + y.","explanation_ar":"wind + y.","dok":1,"skill":"word families","stage":"freer"},{"q":"sun + n + y = ______. Write a sentence.","answer":"sunny – It is sunny and hot.","explanation":"sun + n + y (double n).","explanation_ar":"حرف n مضاعف.","dok":2,"skill":"word families","stage":"freer"},{"q":"cloud + y = ______. Write a sentence.","answer":"cloudy – The sky is cloudy.","explanation":"cloud + y.","explanation_ar":"cloud + y.","dok":2,"skill":"word families","stage":"freer"}]},{"id":"RW-L01-U6-LS1-A4","type":"open","stage":"production","instructions":"Writing: Write about the weather.","instructions_ar":"اكتب عن الطقس.","items":[{"q":"What is the weather like today?","answer":"It is sunny and hot today.","explanation":"It is + weather word.","explanation_ar":"It is + كلمة طقس.","dok":1,"skill":"personal writing","stage":"production"},{"q":"What do you wear on a cold day?","answer":"I wear my coat.","explanation":"I wear + clothes.","explanation_ar":"I wear + ملابس.","dok":1,"skill":"personal writing","stage":"production"},{"q":"What do you do on a rainy day?","answer":"I take my umbrella and I read at home.","explanation":"Action + and.","explanation_ar":"فعل + and.","dok":2,"skill":"personal writing","stage":"production"},{"q":"Which season do you like? Why?","answer":"I like winter because it is cool.","explanation":"Season + because.","explanation_ar":"فصل + because.","dok":2,"skill":"opinion","stage":"production"}]}],"game":{"name":"Weather Spinner","mechanic":"timed_quiz","rules":["On this screen: answer the lesson questions as fast as you can.","In class: Spin wheel: the wheel lands on a weather icon; the child drags the right clothes onto Sami and records \"It is ___. I wear ___.\" Six spins to dress Sami for every weather.","Teams take turns to spin the spinner.","The player says the weather: \"It is windy!\"","The player picks a clothes card and says: \"I wear my coat.\" or \"I take my umbrella.\"","The team decides if it makes sense; yes = 1 point.","First team to 6 points wins."],"data":[]},"exit_quiz":[{"q":"Which word describes a day with a lot of rain?","answer":"rainy","explanation":"Rain + y = rainy.","explanation_ar":"ممطر.","options":["sunny","windy","rainy","hot"],"dok":1,"skill":"word families"},{"q":"Which word describes a day with a lot of sun?","answer":"sunny","explanation":"Sun + n + y = sunny.","explanation_ar":"مشمس.","options":["rainy","cold","sunny","cloud"],"dok":1,"skill":"word families"},{"q":"You hold this over your head in the rain.","answer":"an umbrella","explanation":"Umbrellas keep you dry.","explanation_ar":"المظلة.","options":["an umbrella","a coat","a cloud","the sun"],"dok":1,"skill":"vocabulary"},{"q":"Which season is very hot in Saudi Arabia?","answer":"summer","explanation":"Summer is very hot.","explanation_ar":"الصيف.","options":["winter","summer","rainy","windy"],"dok":1,"skill":"vocabulary"},{"q":"*The palm trees move a lot. It is very windy.* What is a sentence clue for *windy*?","answer":"The palm trees move a lot.","explanation":"Moving trees show wind.","explanation_ar":"حركة الأشجار تدل على الرياح.","options":["It is very.","palm","trees","The palm trees move a lot."],"dok":2,"skill":"sentence clue"},{"q":"Which sentence about today is correct?","answer":"It is cold today.","explanation":"English needs *It is*.","explanation_ar":"نحتاج It is.","options":["Is cold today.","Today cold is.","It cold today.","It is cold today."],"dok":2,"skill":"usage"},{"q":"Which word is a season?","answer":"winter","explanation":"Winter is a season.","explanation_ar":"الشتاء فصل.","options":["cloud","winter","coat","sky"],"dok":1,"skill":"vocabulary"},{"q":"*Weather* means ___.","answer":"how the sky and air are","explanation":"Weather = sunny, rainy, windy…","explanation_ar":"الطقس.","options":["how the sky and air are","a kind of coat","the night sky","a school subject"],"dok":1,"skill":"vocabulary"},{"q":"It is rainy and cold. What do you take?","answer":"a coat and an umbrella","explanation":"Coat for cold; umbrella for rain.","explanation_ar":"معطف ومظلة.","options":["sunglasses and a hat","a T-shirt only","a coat and an umbrella","a fan"],"dok":2,"skill":"reasoning"},{"q":"Why does the word *sunny* have two n's?","answer":"We double the n before adding -y.","explanation":"sun → sunny.","explanation_ar":"نضاعف n قبل y.","options":["It is a long word.","We double the n before adding -y.","It is a name.","It is a mistake."],"dok":3,"skill":"spelling pattern"}],"images":[{"id":"IMG-RW-L01-U6-LS1-V01","prompt":"Picture for the word 'sun': a bright yellow sun"},{"id":"IMG-RW-L01-U6-LS1-V02","prompt":"Picture for the word 'rain': rain drops falling on a roof"},{"id":"IMG-RW-L01-U6-LS1-V03","prompt":"Picture for the word 'wind': palm trees bending in the wind"},{"id":"IMG-RW-L01-U6-LS1-V04","prompt":"Picture for the word 'cloud': a fluffy gray cloud covering the sun"},{"id":"IMG-RW-L01-U6-LS1-V05","prompt":"Picture for the word 'hot': a child fanning himself under a strong sun"},{"id":"IMG-RW-L01-U6-LS1-V06","prompt":"Picture for the word 'cold': a child shivering with a scarf"},{"id":"IMG-RW-L01-U6-LS1-V07","prompt":"Picture for the word 'sunny': a sunny sky over a park"},{"id":"IMG-RW-L01-U6-LS1-V08","prompt":"Picture for the word 'rainy': a rainy street with puddles"},{"id":"IMG-RW-L01-U6-LS1-V09","prompt":"Picture for the word 'windy': a kite flying high and a hat blowing away"},{"id":"IMG-RW-L01-U6-LS1-V10","prompt":"Picture for the word 'summer': children at the beach under a hot sun"},{"id":"IMG-RW-L01-U6-LS1-V11","prompt":"Picture for the word 'winter': a family in coats on a cool cloudy day"},{"id":"IMG-RW-L01-U6-LS1-V12","prompt":"Picture for the word 'umbrella': a red umbrella in the rain"},{"id":"IMG-RW-L01-U6-LS1-V13","prompt":"Picture for the word 'coat': a navy winter coat"},{"id":"IMG-RW-L01-U6-LS1-V14","prompt":"Picture for the word 'sky': a gray sky above palm trees"},{"id":"IMG-RW-L01-U6-LS1-V15","prompt":"Picture for the word 'weather': four small icons: sun, rain, wind, cloud"},{"id":"IMG-RW-L01-U6-LS1-V16","prompt":"Picture for the word 'season': a circle split into summer and winter scenes"},{"id":"IMG-RW-L01-U6-LS1-01","prompt":"Summer at the beach and a rainy winter day in Taif."},{"id":"IMG-RW-L01-U6-LS1-02","prompt":"Six weather icons."},{"id":"IMG-RW-L01-U6-LS1-03","prompt":"Word blocks growing a 'y' at the end."}],"audio":[{"id":"AUD-RW-L01-U6-LS1-V01","script":"sun. The sun is very bright."},{"id":"AUD-RW-L01-U6-LS1-V02","script":"rain. The rain falls on the roof."},{"id":"AUD-RW-L01-U6-LS1-V03","script":"wind. The wind moves the palm trees."},{"id":"AUD-RW-L01-U6-LS1-V04","script":"cloud. A big cloud covers the sun."},{"id":"AUD-RW-L01-U6-LS1-V05","script":"hot. It is hot in summer."},{"id":"AUD-RW-L01-U6-LS1-V06","script":"cold. The water is cold."},{"id":"AUD-RW-L01-U6-LS1-V07","script":"sunny. It is a sunny day."},{"id":"AUD-RW-L01-U6-LS1-V08","script":"rainy. It is a rainy morning."},{"id":"AUD-RW-L01-U6-LS1-V09","script":"windy. It is windy today."},{"id":"AUD-RW-L01-U6-LS1-V10","script":"summer. We swim in summer."},{"id":"AUD-RW-L01-U6-LS1-V11","script":"winter. It rains in winter."},{"id":"AUD-RW-L01-U6-LS1-V12","script":"umbrella. Take your umbrella!"},{"id":"AUD-RW-L01-U6-LS1-V13","script":"coat. Put on your coat."},{"id":"AUD-RW-L01-U6-LS1-V14","script":"sky. The sky is gray today."},{"id":"AUD-RW-L01-U6-LS1-V15","script":"weather. What is the weather like?"},{"id":"AUD-RW-L01-U6-LS1-V16","script":"season. Winter is my favorite season."},{"id":"AUD-RW-L01-U6-LS1-VID","script":"What is the weather like today? Let's look at the sky! The sun! It is sunny. The rain! It is rainy. The wind! It is windy. Look at the cloud. It is gray. A cloud can bring rain. It is cold. Put on your coat! It is rainy. Open your umbrella! In Saudi Arabia, summer is very hot. Winter is cool and sometimes rainy. Use the picture and the sentence to find what words mean. Weather detective!"}]},{"id":"RW-L01-U6-LS2","title":"Rain in the Desert","lesson_type":"close_reading","objectives":["read a short story (about 90 words) and answer who, what, where and when questions","use quotation marks and *says* to find who is talking","explain what Grandpa means when he says rain is a gift"],"objectives_ar":["قراءة قصة قصيرة (نحو 90 كلمة) والإجابة عن أسئلة من وماذا وأين ومتى.","استخدام علامتي التنصيص وكلمة says لمعرفة المتكلم.","شرح ما يقصده الجد بقوله إن المطر نعمة."],"success_criteria":["I can read the story about the rain.","I can find who is talking.","I can explain why rain is a gift."],"success_criteria_ar":["أستطيع قراءة القصة عن المطر.","أستطيع معرفة من يتكلم.","أستطيع شرح لماذا المطر نعمة."],"map_area":"Literary Text: Key Ideas and Details","vocabulary":[{"word":"gray","pos":"adjective","ipa":"/ɡreɪ/","definition":"the color between black and white","arabic":"رمادي","example":"The cat is gray.","image_id":"IMG-RW-L01-U6-LS2-V01","audio_id":"AUD-RW-L01-U6-LS2-V01","tier":"core"},{"word":"dry","pos":"adjective","ipa":"/draɪ/","definition":"with no water","arabic":"جاف","example":"The sand is dry.","image_id":"IMG-RW-L01-U6-LS2-V02","audio_id":"AUD-RW-L01-U6-LS2-V02","tier":"core"},{"word":"fall","pos":"verb","ipa":"/fɔl/","definition":"to come down","arabic":"يسقط / يهطل","example":"Leaves fall from the tree.","image_id":"IMG-RW-L01-U6-LS2-V03","audio_id":"AUD-RW-L01-U6-LS2-V03","tier":"core"},{"word":"outside","pos":"adverb","ipa":"/ˌaʊtˈsaɪd/","definition":"not in a building","arabic":"في الخارج","example":"We play outside.","image_id":"IMG-RW-L01-U6-LS2-V04","audio_id":"AUD-RW-L01-U6-LS2-V04","tier":"core"},{"word":"gift","pos":"noun","ipa":"/ɡɪft/","definition":"something good that is given to you","arabic":"هدية / نعمة","example":"Rain is a gift for the land.","image_id":"IMG-RW-L01-U6-LS2-V05","audio_id":"AUD-RW-L01-U6-LS2-V05","tier":"core"},{"word":"plants","pos":"noun","ipa":"/plænts/","definition":"living green things that grow in soil","arabic":"نباتات","example":"Plants need water.","image_id":"IMG-RW-L01-U6-LS2-V06","audio_id":"AUD-RW-L01-U6-LS2-V06","tier":"core"},{"word":"again","pos":"adverb","ipa":"/əˈɡɛn/","definition":"one more time","arabic":"مرة أخرى","example":"Read it again.","image_id":"IMG-RW-L01-U6-LS2-V07","audio_id":"AUD-RW-L01-U6-LS2-V07","tier":"core"}],"explanation":{"text":"In stories, characters **talk**. Their words are inside **quotation marks**: \" \".\n\nLook for **says** or **asks** near the words. The name next to it tells you **who is talking**: *\"Rain!\" says Sami.*\n\nRead the words in quotation marks in the character's **voice**.","examples":["*\"Look, Grandpa!\" says Sami.* → **Sami** is talking.","*\"Rain!\"* → Sami says this too. It is still Sami's turn.","*\"Rain is a gift,\" he says.* → **he** = Grandpa Saleh.","*\"The desert drinks, and then flowers grow.\"* → Grandpa is still talking.","Who? → Sami, Lama and Grandpa Saleh.","Where? → in Taif, outside in the desert.","When? → in winter.","What happens? → It rains; the children go outside; then the sun comes out.","Think: Why is Sami happy at the end? → He sees new green plants after the rain."],"common_errors":["✗ Reading *says Sami* in Sami's voice. → ✓ Read only the words in \" \" in Sami's voice. (*says Sami* is the narrator.)","✗ \"Look, Grandpa! says Sami.\" → ✓ \"Look, Grandpa!\" says Sami. (Close the quotation marks after the spoken words.)","✗ The rain fall on the sand. → ✓ The rain falls on the sand. (The rain → **falls**.)","✗ Sami put on his coat. → ✓ Sami puts on his coat. (One person → **puts**.)","✗ It is winter in the Taif. → ✓ It is winter in Taif. (No **the** before city names.)","✗ The sky is grey/gray? → ✓ gray (American English spells it **gray**.)"],"arabic":"في القصص تتكلم الشخصيات، وتوضع كلماتها بين علامتي التنصيص \" \".\n\nابحث عن says أو asks قرب الكلمات؛ الاسم المجاور يخبرك من المتكلم: \"Rain!\" says Sami.\n\nاقرأ الكلمات التي بين علامتي التنصيص بصوت الشخصية.\n\nيقول الجد إن المطر نعمة لأن الأرض تشرب فتنبت الأزهار والنباتات."},"video":{"script":[{"time":"00:00–00:20","narration":"Shh! Listen… Is it rain? In the desert?","on_screen":"Rain in the Desert","visual":"A gray sky over Taif; the first drops fall on a window."},{"time":"00:20–01:25","narration":"It is winter in Taif. The sky is gray… \"Look, Grandpa!\" says Sami. \"Rain!\"…","on_screen":"(story text)","visual":"The story is read with voices; speech bubbles appear above Sami and Grandpa when they talk."},{"time":"01:25–01:55","narration":"See these marks? Quotation marks hold the words a character says.","on_screen":"\" \" = talking","visual":"Two big quotation marks open like a door and Sami's words step inside."},{"time":"01:55–02:20","narration":"\"Rain is a gift,\" says Grandpa. The desert drinks, and green plants grow!","on_screen":"Rain is a gift 🌱","visual":"Rain soaks into dry sand; small green plants pop up."},{"time":"02:20–02:40","narration":"Find the quotation marks. Find who is talking. Read it in their voice!","on_screen":"Who is talking?","visual":"Saqr points at a speech bubble and then at Grandpa."}],"captions_ar":["اصمتوا! استمعوا… هل هذا مطر؟ في الصحراء؟","إنه الشتاء في الطائف. السماء رمادية… \"انظر يا جدي!\" يقول سامي. \"مطر!\"","هل ترون هاتين العلامتين؟ علامتا التنصيص تحملان كلام الشخصية.","\"المطر نعمة\" يقول الجد. تشرب الصحراء وتنمو النباتات الخضراء!","ابحث عن علامتي التنصيص، واعرف من يتكلم، واقرأ بصوته!"],"voice":"Narrator: American English, warm female teacher, speed 0.8. Sami: excited boy. Grandpa Saleh: deep, gentle, wise older male voice. Soft rain sound."},"texts":[{"type":"reading","title":"Rain in the Desert","body":"It is winter in Taif. The sky is gray. There are big clouds.\n\n\"Look, Grandpa!\" says Sami. \"Rain!\"\n\nDrop, drop, drop. The rain falls on the dry sand and the palm trees.\n\nSami and Lama run outside. They open an umbrella. The wind is cold, so Sami puts on his coat.\n\nGrandpa Saleh smiles. \"Rain is a gift,\" he says. \"The desert drinks, and then flowers grow.\"\n\nAfter the rain, the sun comes out. The sky is blue again. Sami sees small green plants in the sand. What a happy rainy day!","word_count":92,"audio_id":"AUD-RW-L01-U6-LS2-T1","id":"TXT-RW-L01-U6-LS2-1","genre":"narrative","role":"main","difficulty":"BR–200L","glossary":[{"word":"gift","definition":"something good that is given to you","arabic":"هدية / نعمة"},{"word":"again","definition":"one more time","arabic":"مرة أخرى"}]}],"activities":[{"id":"RW-L01-U6-LS2-A1","type":"mcq","stage":"controlled","instructions":"Controlled practice: Read the story. Choose the answer.","instructions_ar":"اقرأ القصة واختر الإجابة.","items":[{"q":"What season is it in the story?","answer":"winter","explanation":"Text: It is winter in Taif.","explanation_ar":"الشتاء.","options":["summer","spring","winter","fall"],"dok":1,"skill":"key details: when","stage":"controlled"},{"q":"What color is the sky at the start?","answer":"gray","explanation":"Text: The sky is gray.","explanation_ar":"رمادية.","options":["blue","gray","white","pink"],"dok":1,"skill":"key details","stage":"controlled"},{"q":"Where does the rain fall?","answer":"on the dry sand and the palm trees","explanation":"Text: on the dry sand and the palm trees.","explanation_ar":"على الرمل والنخيل.","options":["on the dry sand and the palm trees","on the sea","on the school bus","in the kitchen"],"dok":1,"skill":"key details: where","stage":"controlled"},{"q":"What do Sami and Lama open?","answer":"an umbrella","explanation":"Text: They open an umbrella.","explanation_ar":"مظلة.","options":["a door","a book","an umbrella","a window"],"dok":1,"skill":"key details","stage":"controlled"},{"q":"Why does Sami put on his coat?","answer":"The wind is cold.","explanation":"Text: The wind is cold, so…","explanation_ar":"الرياح باردة.","options":["The sun is hot.","He is going to school.","Grandpa is sad.","The wind is cold."],"dok":1,"skill":"cause and effect","stage":"controlled"},{"q":"What does Sami see after the rain?","answer":"small green plants","explanation":"Text: small green plants in the sand.","explanation_ar":"نباتات خضراء صغيرة.","options":["small green plants","a big camel","snow","a rainbow fish"],"dok":1,"skill":"key details","stage":"controlled"}]},{"id":"RW-L01-U6-LS2-A2","type":"mcq","stage":"guided","instructions":"Guided practice: Who is talking? Choose.","instructions_ar":"مَن يتكلم؟ اختر.","items":[{"q":"Who says *\"Look, Grandpa!\"*?","answer":"Sami","explanation":"says Sami.","explanation_ar":"سامي.","options":["Lama","Grandpa","Sami","Mother"],"dok":1,"skill":"speakers","stage":"guided"},{"q":"Who says *\"Rain is a gift\"*?","answer":"Grandpa Saleh","explanation":"he says – he is Grandpa.","explanation_ar":"الجد صالح.","options":["Grandpa Saleh","Sami","Lama","Mr. Fahad"],"dok":1,"skill":"speakers","stage":"guided"},{"q":"What are the marks \" \" called?","answer":"quotation marks","explanation":"They show talking.","explanation_ar":"علامتا التنصيص.","options":["periods","quotation marks","commas","brackets"],"dok":1,"skill":"punctuation","stage":"guided"},{"q":"In *\"Rain is a gift,\" he says*, who is *he*?","answer":"Grandpa Saleh","explanation":"Grandpa is the one who smiles and talks.","explanation_ar":"الجد.","options":["Sami","the wind","the sun","Grandpa Saleh"],"dok":2,"skill":"pronoun reference","stage":"guided"},{"q":"Which words does Grandpa say?","answer":"The desert drinks, and then flowers grow.","explanation":"These words are in Grandpa's quotation marks.","explanation_ar":"هذه كلمات الجد.","options":["Look, Grandpa!","Rain!","What a happy rainy day!","The desert drinks, and then flowers grow."],"dok":1,"skill":"speakers","stage":"guided"},{"q":"Which sentence has NO one talking?","answer":"The sky is blue again.","explanation":"No quotation marks.","explanation_ar":"لا توجد علامات تنصيص.","options":["\"Rain!\"","The sky is blue again.","\"Look, Grandpa!\" says Sami.","\"Rain is a gift,\" he says."],"dok":2,"skill":"punctuation","stage":"guided"}]},{"id":"RW-L01-U6-LS2-A3","type":"highlight","stage":"freer","instructions":"Find the evidence: Think questions. Underline or choose.","instructions_ar":"أسئلة تفكير: ضع خطًا أو اختر.","items":[{"q":"Underline the sentence that shows the weather changes at the end.","answer":"After the rain, the sun comes out.","explanation":"The sun comes out after the rain.","explanation_ar":"الشمس تشرق بعد المطر.","evidence":"After the rain, the sun comes out.","text_id":"TXT-RW-L01-U6-LS2-1","dok":1,"skill":"evidence","stage":"freer","sentences":["It is winter in Taif.","The sky is gray.","There are big clouds.","\"Look, Grandpa!\" says Sami.","\"Rain!\"","Drop, drop, drop.","The rain falls on the dry sand and the palm trees.","Sami and Lama run outside.","They open an umbrella.","The wind is cold, so Sami puts on his coat.","Grandpa Saleh smiles.","\"Rain is a gift,\" he says.","\"The desert drinks, and then flowers grow.\"","After the rain, the sun comes out.","The sky is blue again.","Sami sees small green plants in the sand.","What a happy rainy day!"]},{"q":"Underline Grandpa's reason that rain is good.","answer":"\"The desert drinks, and then flowers grow.\"","explanation":"This explains why rain is a gift.","explanation_ar":"هذا يشرح لماذا المطر نعمة.","evidence":"\"The desert drinks, and then flowers grow.\"","text_id":"TXT-RW-L01-U6-LS2-1","dok":2,"skill":"evidence","stage":"freer","sentences":["It is winter in Taif.","The sky is gray.","There are big clouds.","\"Look, Grandpa!\" says Sami.","\"Rain!\"","Drop, drop, drop.","The rain falls on the dry sand and the palm trees.","Sami and Lama run outside.","They open an umbrella.","The wind is cold, so Sami puts on his coat.","Grandpa Saleh smiles.","\"Rain is a gift,\" he says.","\"The desert drinks, and then flowers grow.\"","After the rain, the sun comes out.","The sky is blue again.","Sami sees small green plants in the sand.","What a happy rainy day!"]},{"q":"What does Grandpa mean by *Rain is a gift*?","answer":"Rain is good for the land and plants.","explanation":"The desert drinks and flowers grow.","explanation_ar":"المطر نافع للأرض.","options":["Rain is good for the land and plants.","Rain is in a box.","Rain is bad.","Rain is a toy."],"dok":2,"skill":"inference","stage":"freer"},{"q":"How does Sami feel about the rain?","answer":"excited and happy","explanation":"He shouts \"Rain!\" and it is a happy day.","explanation_ar":"متحمس وسعيد.","options":["scared","angry","excited and happy","bored"],"dok":2,"skill":"character feelings","stage":"freer"}]},{"id":"RW-L01-U6-LS2-A4","type":"open","stage":"production","instructions":"Writing: Write and connect.","instructions_ar":"اكتب واربط.","items":[{"q":"Write a line for Lama in quotation marks. Use *says Lama*.","answer":"\"I love the rain!\" says Lama.","explanation":"Words in \" \" + says Lama.","explanation_ar":"كلام بين علامتين + says Lama.","dok":2,"skill":"dialogue","stage":"production"},{"q":"Do you like rainy days? Why?","answer":"Yes, I like rainy days because they are cool.","explanation":"Yes/No + because.","explanation_ar":"نعم/لا + because.","dok":2,"skill":"connect","stage":"production"},{"q":"What do you do when it rains?","answer":"I look out of the window.","explanation":"A true sentence.","explanation_ar":"جملة صحيحة.","dok":1,"skill":"connect","stage":"production"},{"q":"Draw the desert after the rain. Write one sentence.","answer":"Green plants grow in the sand.","explanation":"Drawing + sentence.","explanation_ar":"رسم + جملة.","dok":1,"skill":"visualize","stage":"production"}]},{"id":"RW-L01-U6-LS2-TR-1","type":"timed_reading","instructions":"Timed reading: Read \"Rain in the Desert\" aloud or silently. Try to finish in the time.","instructions_ar":"اقرأ النص وحاول أن تنهيه في الوقت المحدد.","items":[{"q":"Read “Rain in the Desert”.","answer":"92 words","title":"Rain in the Desert","body":"It is winter in Taif. The sky is gray. There are big clouds.\n\n\"Look, Grandpa!\" says Sami. \"Rain!\"\n\nDrop, drop, drop. The rain falls on the dry sand and the palm trees.\n\nSami and Lama run outside. They open an umbrella. The wind is cold, so Sami puts on his coat.\n\nGrandpa Saleh smiles. \"Rain is a gift,\" he says. \"The desert drinks, and then flowers grow.\"\n\nAfter the rain, the sun comes out. The sky is blue again. Sami sees small green plants in the sand. What a happy rainy day!","words":92,"limit":153}],"time_limit_sec":153}],"game":{"name":"Speech Bubble Match","mechanic":"timed_quiz","rules":["On this screen: answer the lesson questions as fast as you can.","In class: Bubble pop: a speech bubble floats up; the child taps the character who says it. Correct = the bubble pops above the character and plays the line in their voice.","Put character cards on the board.","A student takes a speech-bubble card and reads it in a voice.","The team says who is talking and sticks the bubble next to that character.","Correct = 1 point.","Play with 8 bubbles, some from earlier units for fun."],"data":[]},"exit_quiz":[{"q":"Where does the story happen?","answer":"in Taif","explanation":"Text: winter in Taif.","explanation_ar":"في الطائف.","options":["in Jeddah","in Riyadh","in Abha","in Taif"],"dok":1,"skill":"setting"},{"q":"What falls from the clouds?","answer":"rain","explanation":"Rain falls.","explanation_ar":"المطر.","options":["rain","sand","flowers","dates"],"dok":1,"skill":"key details"},{"q":"Who goes outside with Sami?","answer":"Lama","explanation":"Text: Sami and Lama run outside.","explanation_ar":"لمى.","options":["Omar","Noura","Lama","Mother"],"dok":1,"skill":"characters"},{"q":"Quotation marks show ___.","answer":"the words a character says","explanation":"\" \" hold spoken words.","explanation_ar":"كلام الشخصية.","options":["the end of a sentence","a list of food","the title","the words a character says"],"dok":1,"skill":"punctuation"},{"q":"Which word tells us who is talking?","answer":"says","explanation":"says + name.","explanation_ar":"says.","options":["rain","gray","after","says"],"dok":1,"skill":"speakers"},{"q":"What happens after the rain?","answer":"The sun comes out.","explanation":"Text: After the rain, the sun comes out.","explanation_ar":"تشرق الشمس.","options":["It snows.","The sun comes out.","Sami goes to bed.","The clouds get bigger."],"dok":1,"skill":"sequence"},{"q":"*The sand is dry.* *Dry* means ___.","answer":"with no water","explanation":"Dry = no water.","explanation_ar":"جاف.","options":["with no water","very cold","very big","full of water"],"dok":2,"skill":"word in context"},{"q":"*The desert drinks.* What does this mean?","answer":"The sand takes in the rain water.","explanation":"It is a special way to say the ground gets water.","explanation_ar":"الأرض تمتص ماء المطر.","options":["The desert has a cup.","The sand takes in the rain water.","Camels drink tea.","Sami drinks water."],"dok":3,"skill":"figurative language"},{"q":"Why is it *a happy rainy day*?","answer":"The rain is good and new plants grow.","explanation":"Rain brings new life.","explanation_ar":"المطر نعمة وتنمو النباتات.","options":["Sami is sick.","The rain is good and new plants grow.","The umbrella is broken.","It is very hot."],"dok":2,"skill":"inference"},{"q":"Which is the best title for the story's message?","answer":"Rain Brings New Life","explanation":"The story shows plants growing after rain.","explanation_ar":"المطر يجلب حياة جديدة.","options":["A Hot Day at the Beach","Lama's New Bag","Rain Brings New Life","Grandpa Goes to Riyadh"],"dok":3,"skill":"theme"}],"images":[{"id":"IMG-RW-L01-U6-LS2-V01","prompt":"Picture for the word 'gray': a gray cloud and a gray stone"},{"id":"IMG-RW-L01-U6-LS2-V02","prompt":"Picture for the word 'dry': cracked dry ground"},{"id":"IMG-RW-L01-U6-LS2-V03","prompt":"Picture for the word 'fall': rain drops falling"},{"id":"IMG-RW-L01-U6-LS2-V04","prompt":"Picture for the word 'outside': children playing outside a house"},{"id":"IMG-RW-L01-U6-LS2-V05","prompt":"Picture for the word 'gift': a wrapped gift box with a raindrop pattern"},{"id":"IMG-RW-L01-U6-LS2-V06","prompt":"Picture for the word 'plants': small green plants growing in sand"},{"id":"IMG-RW-L01-U6-LS2-V07","prompt":"Picture for the word 'again': a circular arrow"},{"id":"IMG-RW-L01-U6-LS2-01","prompt":"Sami, Lama and Grandpa Saleh watch rain falling on the sand."},{"id":"IMG-RW-L01-U6-LS2-02","prompt":"After the rain, Sami looks at new green plants in the sand."},{"id":"IMG-RW-L01-U6-LS2-03","prompt":"Quotation marks drawn like a door with a speech bubble going in."}],"audio":[{"id":"AUD-RW-L01-U6-LS2-V01","script":"gray. The cat is gray."},{"id":"AUD-RW-L01-U6-LS2-V02","script":"dry. The sand is dry."},{"id":"AUD-RW-L01-U6-LS2-V03","script":"fall. Leaves fall from the tree."},{"id":"AUD-RW-L01-U6-LS2-V04","script":"outside. We play outside."},{"id":"AUD-RW-L01-U6-LS2-V05","script":"gift. Rain is a gift for the land."},{"id":"AUD-RW-L01-U6-LS2-V06","script":"plants. Plants need water."},{"id":"AUD-RW-L01-U6-LS2-V07","script":"again. Read it again."},{"id":"AUD-RW-L01-U6-LS2-T1","script":"It is winter in Taif. The sky is gray. There are big clouds. \"Look, Grandpa!\" says Sami. \"Rain!\" Drop, drop, drop. The rain falls on the dry sand and the palm trees. Sami and Lama run outside. They open an umbrella. The wind is cold, so Sami puts on his coat. Grandpa Saleh smiles. \"Rain is a gift,\" he says. \"The desert drinks, and then flowers grow.\" After the rain, the sun comes out. The sky is blue again. Sami sees small green plants in the sand. What a happy rainy day!"},{"id":"AUD-RW-L01-U6-LS2-VID","script":"Shh! Listen… Is it rain? In the desert? It is winter in Taif. The sky is gray… \"Look, Grandpa!\" says Sami. \"Rain!\"… See these marks? Quotation marks hold the words a character says. \"Rain is a gift,\" says Grandpa. The desert drinks, and green plants grow! Find the quotation marks. Find who is talking. Read it in their voice!"}]},{"id":"RW-L01-U6-LS3","title":"Main topic: what is it all about?: \"Meet Mr. Fahad, the Weather Man\"","lesson_type":"strategy_paired_text","objectives":["say the main topic of a text: what is it all about?","find key details that tell about the main topic","read a short profile of a person and say what his job is"],"objectives_ar":["تحديد الموضوع الرئيسي للنص: عمّ يتحدث كله؟","إيجاد التفاصيل المهمة التي تتحدث عن الموضوع الرئيسي.","قراءة نبذة قصيرة عن شخص وقول ما عمله."],"success_criteria":["I can say what a text is all about.","I can find details that tell about the topic.","I can say what Mr. Fahad does."],"success_criteria_ar":["أستطيع قول عمّ يتحدث النص كله.","أستطيع إيجاد تفاصيل عن الموضوع.","أستطيع قول ما يفعله الأستاذ فهد."],"map_area":"Informational Text: Key Ideas and Details","vocabulary":[{"word":"topic","pos":"noun","ipa":"/ˈtɑpɪk/","definition":"what a text is all about","arabic":"موضوع","example":"The topic is rain.","image_id":"IMG-RW-L01-U6-LS3-V01","audio_id":"AUD-RW-L01-U6-LS3-V01","tier":"core"},{"word":"job","pos":"noun","ipa":"/dʒɑb/","definition":"the work a person does","arabic":"وظيفة / عمل","example":"My uncle's job is teaching.","image_id":"IMG-RW-L01-U6-LS3-V02","audio_id":"AUD-RW-L01-U6-LS3-V02","tier":"core"},{"word":"TV","pos":"noun","ipa":"/ˌtiˈvi/","definition":"a box with a screen for shows and news","arabic":"تلفاز","example":"We watch the news on TV.","image_id":"IMG-RW-L01-U6-LS3-V03","audio_id":"AUD-RW-L01-U6-LS3-V03","tier":"core"},{"word":"map","pos":"noun","ipa":"/mæp/","definition":"a drawing of a place from above","arabic":"خريطة","example":"Look at the map of Saudi Arabia.","image_id":"IMG-RW-L01-U6-LS3-V04","audio_id":"AUD-RW-L01-U6-LS3-V04","tier":"core"},{"word":"tell","pos":"verb","ipa":"/tɛl/","definition":"to give information by speaking","arabic":"يخبر","example":"Tell me about your day.","image_id":"IMG-RW-L01-U6-LS3-V05","audio_id":"AUD-RW-L01-U6-LS3-V05","tier":"core"},{"word":"people","pos":"noun","ipa":"/ˈpipəl/","definition":"men, women and children","arabic":"الناس","example":"Many people live in Riyadh.","image_id":"IMG-RW-L01-U6-LS3-V06","audio_id":"AUD-RW-L01-U6-LS3-V06","tier":"core"},{"word":"about","pos":"preposition","ipa":"/əˈbaʊt/","definition":"on the subject of","arabic":"عن / حول","example":"This book is about camels.","image_id":"IMG-RW-L01-U6-LS3-V07","audio_id":"AUD-RW-L01-U6-LS3-V07","tier":"core"}],"explanation":{"text":"The **main topic** is what the **whole text** is about. Say it in a few words.\n\nFind it with three clues: the **title**, the **first sentence** and the word you see **many times**.\n\n**Key details** tell more about the main topic. Use the **Main-Idea Umbrella**: the topic goes on top; the details go under it.","examples":["*Meet Mr. Fahad, the Weather Man* → main topic: **Mr. Fahad's job**.","Clue 1 (title): *the Weather Man*.","Clue 2 (first sentence): *He tells people about the weather.*","Clue 3 (many times): **he / Mr. Fahad**, **weather**.","Detail: He works on TV in Riyadh.","Detail: He looks at the sky, the clouds and the wind.","Detail: He uses computers and maps.","*Rain in the Desert* → main topic: **a rainy day in the desert**.","*Animals on the Move* (Unit 4) → main topic: **how animals move**."],"common_errors":["✗ The main topic is maps. → ✓ The main topic is Mr. Fahad's job. Maps are a detail. (One small detail is not the whole topic.)","✗ The topic is: He uses computers and maps and he looks at the sky and… → ✓ The topic is Mr. Fahad's job. (Say the topic in a few words.)","✗ Mr. Fahad work on TV. → ✓ Mr. Fahad works on TV. (One person → **works**.)","✗ He tell people the weather. → ✓ He tells people about the weather. (Say **tells people about**.)","✗ The text is about a weather. → ✓ The text is about the weather. (Say **the weather**.)","✗ He helps people to get ready. → ✓ He helps people get ready. (Both are OK; *help people get* is most common.)"],"arabic":"الموضوع الرئيسي هو ما يتحدث عنه النص كله، ونقوله في كلمات قليلة.\n\nاكتشفه بثلاثة أدلة: العنوان، والجملة الأولى، والكلمة التي تتكرر كثيرًا.\n\nالتفاصيل المهمة تخبرنا بالمزيد عن الموضوع. استخدم مظلة الفكرة الرئيسية: الموضوع في الأعلى والتفاصيل تحتها.\n\nانتبه: تفصيل صغير واحد مثل الخرائط ليس هو الموضوع كله."},"video":{"script":[{"time":"00:00–00:15","narration":"Good morning! I am Mr. Fahad, and here is today's weather!","on_screen":"Meet Mr. Fahad","visual":"Mr. Fahad stands in front of a weather map of Saudi Arabia in a TV studio."},{"time":"00:15–00:50","narration":"Mr. Fahad works on TV in Riyadh. He tells people about the weather…","on_screen":"(profile text)","visual":"Scenes: Mr. Fahad looks at clouds, types on a computer, points at a map."},{"time":"00:50–01:20","narration":"What is it ALL about? Look at the title, the first sentence and the words you see many times.","on_screen":"Title · First sentence · Many times","visual":"Three clue cards light up in turn."},{"time":"01:20–01:50","narration":"The main topic is Mr. Fahad's job. It goes on top of the umbrella. Details go underneath.","on_screen":"Main-Idea Umbrella ☂️","visual":"A big umbrella opens: 'Mr. Fahad's job' on top; three detail drops hang below."},{"time":"01:50–02:20","narration":"Maps? That is one detail. The whole text is about his job!","on_screen":"Detail vs. main topic","visual":"A small 'maps' drop tries to sit on top of the umbrella and slides back down."}],"captions_ar":["صباح الخير! أنا الأستاذ فهد، وإليكم طقس اليوم!","يعمل الأستاذ فهد في التلفاز في الرياض، ويخبر الناس عن الطقس…","عمّ يتحدث النص كله؟ انظر إلى العنوان والجملة الأولى والكلمات المتكررة.","الموضوع الرئيسي هو عمل الأستاذ فهد، ونضعه أعلى المظلة، والتفاصيل تحتها.","الخرائط؟ إنها تفصيل واحد. النص كله عن عمله!"],"voice":"Narrator: American English, warm female teacher, speed 0.8. Mr. Fahad: clear, friendly adult male TV-presenter voice."},"texts":[{"type":"reading","title":"Meet Mr. Fahad, the Weather Man","body":"Mr. Fahad works on TV in Riyadh. He tells people about the weather.\n\nEvery morning, he looks at the sky, the clouds and the wind. He uses computers and maps.\n\nThen he says, \"Today is sunny and hot,\" or \"Take an umbrella!\"\n\nMr. Fahad likes his job. He helps people get ready for the day.","word_count":55,"audio_id":"AUD-RW-L01-U6-LS3-T1","id":"TXT-RW-L01-U6-LS3-1","genre":"biography","role":"paired","difficulty":"BR–200L","glossary":[{"word":"TV","definition":"television","arabic":"التلفاز"},{"word":"get ready","definition":"prepare","arabic":"يستعد"}]}],"activities":[{"id":"RW-L01-U6-LS3-A1","type":"mcq","stage":"controlled","instructions":"Controlled practice: Read *Meet Mr. Fahad, the Weather Man*. Choose the answer.","instructions_ar":"اقرأ النص واختر الإجابة.","items":[{"q":"Where does Mr. Fahad work?","answer":"on TV in Riyadh","explanation":"Text: works on TV in Riyadh.","explanation_ar":"في التلفاز بالرياض.","options":["at a school in Taif","on a farm","on TV in Riyadh","in a café"],"dok":1,"skill":"key details","text_id":"TXT-RW-L01-U6-LS3-1","stage":"controlled"},{"q":"What does he tell people about?","answer":"the weather","explanation":"Text: about the weather.","explanation_ar":"عن الطقس.","options":["food","the weather","animals","school"],"dok":1,"skill":"key details","stage":"controlled"},{"q":"When does he look at the sky?","answer":"every morning","explanation":"Text: Every morning.","explanation_ar":"كل صباح.","options":["every morning","every night","on Fridays only","never"],"dok":1,"skill":"key details: when","stage":"controlled"},{"q":"What does he use?","answer":"computers and maps","explanation":"Text: computers and maps.","explanation_ar":"الحواسيب والخرائط.","options":["a ball and a kite","pens and paint","plates and spoons","computers and maps"],"dok":1,"skill":"key details","stage":"controlled"},{"q":"What might he say on a rainy day?","answer":"\"Take an umbrella!\"","explanation":"Umbrellas are for rain.","explanation_ar":"خذ مظلة.","options":["\"Today is sunny and hot.\"","\"Take an umbrella!\"","\"Good night!\"","\"Eat dates!\""],"dok":2,"skill":"inference","stage":"controlled"},{"q":"How does he help people?","answer":"He helps them get ready for the day.","explanation":"Text: He helps people get ready for the day.","explanation_ar":"يساعدهم على الاستعداد.","options":["He cooks breakfast.","He drives the bus.","He teaches math.","He helps them get ready for the day."],"dok":1,"skill":"key details","stage":"controlled"}]},{"id":"RW-L01-U6-LS3-A2","type":"mcq","stage":"guided","instructions":"Guided practice: Main topic or detail? Choose.","instructions_ar":"موضوع رئيسي أم تفصيل؟ اختر.","items":[{"q":"What is the main topic of *Meet Mr. Fahad, the Weather Man*?","answer":"Mr. Fahad's job","explanation":"The whole text is about his job.","explanation_ar":"عمله.","options":["maps","Mr. Fahad's job","Riyadh","computers"],"dok":1,"skill":"main topic","stage":"guided"},{"q":"Which is a DETAIL, not the main topic?","answer":"He uses maps.","explanation":"Maps are one small fact.","explanation_ar":"تفصيل صغير.","options":["Mr. Fahad's job","a weather man's work","what Mr. Fahad does","He uses maps."],"dok":2,"skill":"detail vs. topic","stage":"guided"},{"q":"What is the main topic of *Rain in the Desert*?","answer":"a rainy day in the desert","explanation":"The whole story is about the rainy day.","explanation_ar":"يوم ممطر في الصحراء.","options":["a rainy day in the desert","a gray cloud","Lama's umbrella","a coat"],"dok":1,"skill":"main topic","stage":"guided"},{"q":"Which clue helps you find the main topic first?","answer":"the title","explanation":"The title is a big clue.","explanation_ar":"العنوان.","options":["the last word","the page number","the title","the color of the page"],"dok":1,"skill":"strategy","stage":"guided"},{"q":"Which word do you see many times in the profile?","answer":"he / Mr. Fahad","explanation":"He/Mr. Fahad appears many times.","explanation_ar":"هو/الأستاذ فهد.","options":["he / Mr. Fahad","camel","school","dinner"],"dok":1,"skill":"strategy","stage":"guided"},{"q":"Which detail tells about Mr. Fahad's job?","answer":"He looks at the sky, the clouds and the wind.","explanation":"It is from the profile and is about his work.","explanation_ar":"تفصيل عن عمله.","options":["Grandpa smiles.","Lama opens an umbrella.","He looks at the sky, the clouds and the wind.","Sami sees plants."],"dok":2,"skill":"key details","stage":"guided"}]},{"id":"RW-L01-U6-LS3-A3","type":"organizer","stage":"freer","instructions":"Organizer: Make a Main-Idea Umbrella for the profile.","instructions_ar":"اصنع مظلة الفكرة الرئيسية للنص.","items":[{"q":"Umbrella (main topic):","answer":"Mr. Fahad's job","explanation":"A few words for the whole text.","explanation_ar":"كلمات قليلة للنص كله.","dok":2,"skill":"main topic","stage":"freer"},{"q":"Raindrop 1 (detail):","answer":"He works on TV in Riyadh.","explanation":"A key detail.","explanation_ar":"تفصيل مهم.","dok":1,"skill":"key details","stage":"freer"},{"q":"Raindrop 2 (detail):","answer":"He looks at the sky every morning.","explanation":"A key detail.","explanation_ar":"تفصيل مهم.","dok":1,"skill":"key details","stage":"freer"},{"q":"Raindrop 3 (detail):","answer":"He uses computers and maps.","explanation":"A key detail.","explanation_ar":"تفصيل مهم.","dok":1,"skill":"key details","stage":"freer"}]},{"id":"RW-L01-U6-LS3-A4","type":"open","stage":"production","instructions":"Writing: Write about jobs and topics.","instructions_ar":"اكتب عن الوظائف والمواضيع.","items":[{"q":"Write the main topic of *Rain in the Desert* in a few words.","answer":"a rainy day in the desert","explanation":"A short topic.","explanation_ar":"موضوع قصير.","dok":2,"skill":"main topic","stage":"production"},{"q":"Write one detail from *Rain in the Desert*.","answer":"The rain falls on the palm trees.","explanation":"One detail.","explanation_ar":"تفصيل واحد.","dok":1,"skill":"key details","stage":"production"},{"q":"Would you like Mr. Fahad's job? Why?","answer":"Yes, because I like maps and computers.","explanation":"Yes/No + because.","explanation_ar":"نعم/لا + because.","dok":3,"skill":"evaluate","stage":"production"},{"q":"Write about a job you know. Use: ___ works in ___. He/She ___.","answer":"My aunt works in a hospital. She helps sick people.","explanation":"Two sentences.","explanation_ar":"جملتان.","dok":2,"skill":"connect","stage":"production"}]},{"id":"RW-L01-U6-LS3-TR-1","type":"timed_reading","instructions":"Timed reading: Read \"Meet Mr. Fahad, the Weather Man\" aloud or silently. Try to finish in the time.","instructions_ar":"اقرأ النص وحاول أن تنهيه في الوقت المحدد.","items":[{"q":"Read “Meet Mr. Fahad, the Weather Man”.","answer":"55 words","title":"Meet Mr. Fahad, the Weather Man","body":"Mr. Fahad works on TV in Riyadh. He tells people about the weather.\n\nEvery morning, he looks at the sky, the clouds and the wind. He uses computers and maps.\n\nThen he says, \"Today is sunny and hot,\" or \"Take an umbrella!\"\n\nMr. Fahad likes his job. He helps people get ready for the day.","words":55,"limit":97}],"time_limit_sec":97},{"id":"RW-L01-U6-LS3-ORG","type":"organizer","organizer":"Main-Idea Umbrella","instructions":"Organizer: Write the main topic on the umbrella. Write three key details in the raindrops.","items":[{"q":"Umbrella: main topic","answer":"Mr. Fahad's job"},{"q":"Raindrop 1: detail","answer":"He works on TV in Riyadh."},{"q":"Raindrop 2: detail","answer":"He looks at the sky, clouds and wind."},{"q":"Raindrop 3: detail","answer":"He uses computers and maps."}]}],"game":{"name":"Umbrella Drop","mechanic":"timed_quiz","rules":["On this screen: answer the lesson questions as fast as you can.","In class: Umbrella catch: sentences fall like raindrops; the child moves the umbrella to catch the main topic and lets details fall into the 'details' puddle. 10 drops per round.","The teacher reads a sentence card about one text.","If it is the main topic, a student puts it ON the umbrella.","If it is a detail, the student puts it UNDER the umbrella.","The class checks: correct = 1 point.","Play with cards from both texts."],"data":[]},"exit_quiz":[{"q":"The main topic is ___.","answer":"what the whole text is about","explanation":"Main topic = the whole text.","explanation_ar":"الموضوع الرئيسي = النص كله.","options":["the last word","a small detail","what the whole text is about","the title page"],"dok":1,"skill":"strategy"},{"q":"What is Mr. Fahad's job?","answer":"He is a weather man on TV.","explanation":"He tells people about the weather on TV.","explanation_ar":"مذيع الطقس.","options":["He is a weather man on TV.","He is a teacher.","He is a farmer.","He is a cook."],"dok":1,"skill":"key details"},{"q":"Which is a key detail about Mr. Fahad?","answer":"He uses computers and maps.","explanation":"This is from his profile.","explanation_ar":"من النبذة عنه.","options":["Lama has an umbrella.","Dates are sweet.","A fish can swim.","He uses computers and maps."],"dok":1,"skill":"key details"},{"q":"Which clue helps you find the main topic?","answer":"the first sentence","explanation":"The first sentence often tells the topic.","explanation_ar":"الجملة الأولى.","options":["the first sentence","the commas","the page color","the last letter"],"dok":1,"skill":"strategy"},{"q":"*He helps people get ready for the day.* What does *get ready* mean?","answer":"prepare","explanation":"Get ready = prepare.","explanation_ar":"يستعد.","options":["sleep","forget","run fast","prepare"],"dok":2,"skill":"word in context"},{"q":"Why does Mr. Fahad look at the sky every morning?","answer":"to know the weather for the day","explanation":"He tells people the weather.","explanation_ar":"ليعرف الطقس.","options":["to find birds","to know the weather for the day","to count stars","to see the moon"],"dok":2,"skill":"inference"},{"q":"What kind of text is *Meet Mr. Fahad, the Weather Man*?","answer":"a text about a real person's life and job","explanation":"It tells about one person.","explanation_ar":"نبذة عن شخص.","options":["a play","a poem","a text about a real person's life and job","a menu"],"dok":2,"skill":"genre"},{"q":"Which is NOT a good main topic for the profile?","answer":"computers","explanation":"Computers are only a detail.","explanation_ar":"الحواسيب تفصيل.","options":["Mr. Fahad's job","computers","a weather man's work","what a weather man does"],"dok":2,"skill":"detail vs. topic"},{"q":"What would Mr. Fahad say on a hot day?","answer":"\"Drink water and wear a hat!\"","explanation":"Hot days need water and hats.","explanation_ar":"اشرب ماء والبس قبعة.","options":["\"Drink water and wear a hat!\"","\"Take your coat!\"","\"It is snowy!\"","\"Open your umbrella!\""],"dok":3,"skill":"inference"},{"q":"How are *Rain in the Desert* and the profile the SAME?","answer":"Both are about weather.","explanation":"Both texts are about weather.","explanation_ar":"كلاهما عن الطقس.","options":["Both are plays.","Both are about weather.","Both are about food.","Both have Lama."],"dok":3,"skill":"compare"}],"images":[{"id":"IMG-RW-L01-U6-LS3-V01","prompt":"Picture for the word 'topic': an umbrella over three small pictures about rain"},{"id":"IMG-RW-L01-U6-LS3-V02","prompt":"Picture for the word 'job': a row of people in work clothes: doctor, pilot, teacher"},{"id":"IMG-RW-L01-U6-LS3-V03","prompt":"Picture for the word 'TV': a TV showing a weather map"},{"id":"IMG-RW-L01-U6-LS3-V04","prompt":"Picture for the word 'map': a simple map with weather icons"},{"id":"IMG-RW-L01-U6-LS3-V05","prompt":"Picture for the word 'tell': a man talking to a group of listeners"},{"id":"IMG-RW-L01-U6-LS3-V06","prompt":"Picture for the word 'people': a crowd of different people smiling"},{"id":"IMG-RW-L01-U6-LS3-V07","prompt":"Picture for the word 'about': a book with a camel on the cover"},{"id":"IMG-RW-L01-U6-LS3-01","prompt":"Mr. Fahad points to a weather map in a TV studio."},{"id":"IMG-RW-L01-U6-LS3-02","prompt":"An umbrella with three raindrops under it for details."},{"id":"IMG-RW-L01-U6-LS3-03","prompt":"Mr. Fahad watching clouds, using a computer and pointing at a map."}],"audio":[{"id":"AUD-RW-L01-U6-LS3-V01","script":"topic. The topic is rain."},{"id":"AUD-RW-L01-U6-LS3-V02","script":"job. My uncle's job is teaching."},{"id":"AUD-RW-L01-U6-LS3-V03","script":"TV. We watch the news on TV."},{"id":"AUD-RW-L01-U6-LS3-V04","script":"map. Look at the map of Saudi Arabia."},{"id":"AUD-RW-L01-U6-LS3-V05","script":"tell. Tell me about your day."},{"id":"AUD-RW-L01-U6-LS3-V06","script":"people. Many people live in Riyadh."},{"id":"AUD-RW-L01-U6-LS3-V07","script":"about. This book is about camels."},{"id":"AUD-RW-L01-U6-LS3-T1","script":"Mr. Fahad works on TV in Riyadh. He tells people about the weather. Every morning, he looks at the sky, the clouds and the wind. He uses computers and maps. Then he says, \"Today is sunny and hot,\" or \"Take an umbrella!\" Mr. Fahad likes his job. He helps people get ready for the day."},{"id":"AUD-RW-L01-U6-LS3-VID","script":"Good morning! I am Mr. Fahad, and here is today's weather! Mr. Fahad works on TV in Riyadh. He tells people about the weather… What is it ALL about? Look at the title, the first sentence and the words you see many times. The main topic is Mr. Fahad's job. It goes on top of the umbrella. Details go underneath. Maps? That is one detail. The whole text is about his job!"}]},{"id":"RW-L01-U6-LS4","title":"Writing Skill: Writing a postcard","lesson_type":"writing_skill","objectives":["name the parts of a postcard: greeting, message, closing, name and address","write a postcard message that tells where you are, the weather and what you do","use commas after the greeting and the closing"],"objectives_ar":["تسمية أجزاء البطاقة البريدية: التحية، الرسالة، الخاتمة، الاسم، العنوان.","كتابة رسالة بطاقة بريدية تخبر بالمكان والطقس وما تفعله.","استخدام الفاصلة بعد التحية والخاتمة."],"success_criteria":["I can find the parts of a postcard.","I can write where I am, the weather and what I do.","I can put commas after Dear… and Love,."],"success_criteria_ar":["أستطيع إيجاد أجزاء البطاقة البريدية.","أستطيع كتابة مكاني والطقس وما أفعله.","أستطيع وضع الفاصلة بعد Dear… وLove,."],"map_area":"Language Usage: Write, Revise Texts for Purpose and Audience (cross-strand)","vocabulary":[{"word":"postcard","pos":"noun","ipa":"/ˈpoʊstˌkɑrd/","definition":"a card with a picture that you send by mail","arabic":"بطاقة بريدية","example":"Noura sends a postcard.","image_id":"IMG-RW-L01-U6-LS4-V01","audio_id":"AUD-RW-L01-U6-LS4-V01","tier":"core"},{"word":"address","pos":"noun","ipa":"/ˈædrɛs/","definition":"the name of the street and city where someone lives","arabic":"عنوان (السكن)","example":"Write the address on the right.","image_id":"IMG-RW-L01-U6-LS4-V02","audio_id":"AUD-RW-L01-U6-LS4-V02","tier":"core"},{"word":"stamp","pos":"noun","ipa":"/stæmp/","definition":"a small paper you stick on mail to send it","arabic":"طابع بريد","example":"Put a stamp on the postcard.","image_id":"IMG-RW-L01-U6-LS4-V03","audio_id":"AUD-RW-L01-U6-LS4-V03","tier":"core"},{"word":"trip","pos":"noun","ipa":"/trɪp/","definition":"a short journey to visit a place","arabic":"رحلة","example":"We go on a trip to Abha.","image_id":"IMG-RW-L01-U6-LS4-V04","audio_id":"AUD-RW-L01-U6-LS4-V04","tier":"core"},{"word":"visit","pos":"verb","ipa":"/ˈvɪzət/","definition":"to go and see a place or a person","arabic":"يزور","example":"We visit Grandma on Friday.","image_id":"IMG-RW-L01-U6-LS4-V05","audio_id":"AUD-RW-L01-U6-LS4-V05","tier":"core"},{"word":"cool","pos":"adjective","ipa":"/kul/","definition":"a little cold, in a nice way","arabic":"معتدل البرودة / منعش","example":"Abha is cool in summer.","image_id":"IMG-RW-L01-U6-LS4-V06","audio_id":"AUD-RW-L01-U6-LS4-V06","tier":"core"},{"word":"mountains","pos":"noun","ipa":"/ˈmaʊntənz/","definition":"very high land","arabic":"جبال","example":"The mountains are green.","image_id":"IMG-RW-L01-U6-LS4-V07","audio_id":"AUD-RW-L01-U6-LS4-V07","tier":"core"}],"explanation":{"text":"A **postcard** is a short note with a picture. We send it from a **trip** to a friend or family.\n\nIt has five parts: **greeting** (Dear Layla,) · **message** · **closing** (Love, / Your friend,) · **your name** · the friend's **address** on the right side.\n\nIn the message, tell **where** you are, what the **weather** is like and what you **do** or **wear**.\n\nPut a **comma** after the greeting and after the closing.","examples":["Greeting: **Dear Omar,**","Greeting: **Dear Grandpa,**","Where: **I am in Jeddah with my uncle.**","Weather: **It is hot and sunny here.**","Weather: **It is cool and windy in Abha.**","Do/wear: **I swim in the Red Sea. I wear a hat.**","Last line: **See you soon!**","Closing: **Love,** / **Your friend,**","Address: **Omar Haddad, 5 Market Street, Riyadh**"],"common_errors":["✗ Dear Layla. → ✓ Dear Layla, (Use a **comma** after the greeting.)","✗ Love Noura (one line) → ✓ Love, / Noura (Comma after Love; name on the next line.)","✗ I am in abha. → ✓ I am in Abha. (Places start with a capital letter.)","✗ Here is cool. → ✓ It is cool here. (Use **It is … here**.)","✗ dear layla, → ✓ Dear Layla, (Capitals for Dear and the name.)","✗ Writing the address at the top of the message. → ✓ Write the address on the right side. (The address has its own place.)"],"arabic":"البطاقة البريدية رسالة قصيرة عليها صورة، نرسلها من رحلة إلى صديق أو قريب.\n\nلها خمسة أجزاء: التحية (Dear Layla,)، والرسالة، والخاتمة (Love,)، واسمك، وعنوان صديقك على الجهة اليمنى.\n\nفي الرسالة اكتب أين أنت، وكيف الطقس، وماذا تفعل أو تلبس.\n\nضع فاصلة بعد التحية وبعد الخاتمة، وانتبه: نقول It is cool here ولا نقول Here is cool."},"video":{"script":[{"time":"00:00–00:15","narration":"Noura is on a trip to Abha! She writes a postcard to Layla.","on_screen":"A Postcard from Abha","visual":"A postcard flips: the front shows green mountains; Noura writes on the back."},{"time":"00:15–00:40","narration":"First, the greeting: Dear Layla, – with a comma!","on_screen":"Dear Layla,","visual":"A comma drops after 'Layla' with a 'plink'."},{"time":"00:40–01:15","narration":"The message: Where? I am in Abha. Weather? It is cool and cloudy. What do I do? I wear my coat. We eat corn.","on_screen":"Where · Weather · Do","visual":"Three icons (map pin, cloud, coat) light up as each sentence appears."},{"time":"01:15–01:40","narration":"The closing: Love, – comma! – and my name: Noura.","on_screen":"Love, / Noura","visual":"The closing and name appear on separate lines."},{"time":"01:40–02:05","narration":"The address goes on the right. Then add a stamp!","on_screen":"Address + stamp ✉️","visual":"A falcon stamp sticks on; the address lines fill in."},{"time":"02:05–02:30","narration":"Greeting, message, closing, name, address. Now write your postcard!","on_screen":"5 parts of a postcard","visual":"Five parts glow in order; Saqr carries the postcard away like a mail bird."}],"captions_ar":["نورة في رحلة إلى أبها! تكتب بطاقة بريدية إلى ليلى.","أولًا التحية: Dear Layla, مع فاصلة!","الرسالة: أين؟ أنا في أبها. الطقس؟ معتدل وغائم. ماذا أفعل؟ ألبس معطفي، ونأكل الذرة.","الخاتمة: Love, مع فاصلة، ثم اسمي: نورة.","العنوان على الجهة اليمنى، ثم أضف الطابع!","التحية، الرسالة، الخاتمة، الاسم، العنوان. والآن اكتب بطاقتك!"],"voice":"Narrator: American English, warm female teacher, speed 0.8. Noura: happy, excited girl voice on holiday. Gentle mountain wind sound."},"texts":[{"type":"model","title":"A Postcard from Abha (from Noura)","body":"Dear Layla,\n\nI am in Abha with my family. It is cool and cloudy here. The mountains are green and beautiful! Today it is windy, so I wear my coat. We eat corn and drink hot milk.\n\nSee you soon!\n\nLove,\n\nNoura\n\n*Address side: Layla Mansour, 12 Palm Street, Taif*","word_count":50,"audio_id":"AUD-RW-L01-U6-LS4-T1","id":"TXT-RW-L01-U6-LS4-1","genre":"model text","role":"model","difficulty":"BR–200L","glossary":[],"annotations":["**Dear Layla,** – the greeting, with a comma.","**I am in Abha** – say WHERE you are.","**It is cool and cloudy here.** – say what the WEATHER is like.","**I wear my coat. We eat corn…** – say what you WEAR and DO.","**See you soon!** – a friendly last line.","**Love,** – the closing, with a comma. **Noura** – your name on its own line.","The address goes on the right side: name, street, city."]}],"activities":[{"id":"RW-L01-U6-LS4-A1","type":"mcq","stage":"controlled","instructions":"Controlled practice: Name the part of the postcard.","instructions_ar":"سمِّ جزء البطاقة البريدية.","items":[{"q":"*Dear Layla,* is the ___.","answer":"greeting","explanation":"It starts the postcard.","explanation_ar":"التحية.","options":["closing","address","stamp","greeting"],"dok":1,"skill":"postcard parts","stage":"controlled"},{"q":"*Love,* is the ___.","answer":"closing","explanation":"It ends the message.","explanation_ar":"الخاتمة.","options":["greeting","message","address","closing"],"dok":1,"skill":"postcard parts","stage":"controlled"},{"q":"*12 Palm Street, Taif* is the ___.","answer":"address","explanation":"Street and city = address.","explanation_ar":"العنوان.","options":["greeting","closing","address","message"],"dok":1,"skill":"postcard parts","stage":"controlled"},{"q":"Where does the address go?","answer":"on the right side","explanation":"The address has its own side.","explanation_ar":"على الجهة اليمنى.","options":["at the top of the message","on the right side","after Dear","under Love,"],"dok":1,"skill":"postcard parts","stage":"controlled"},{"q":"Which sentence tells the WEATHER?","answer":"It is cool and cloudy here.","explanation":"Cool and cloudy are weather words.","explanation_ar":"كلمات طقس.","options":["I am in Abha.","See you soon!","It is cool and cloudy here.","Love,"],"dok":1,"skill":"message","stage":"controlled"},{"q":"Which sentence tells WHERE Noura is?","answer":"I am in Abha with my family.","explanation":"Abha is a place.","explanation_ar":"أبها مكان.","options":["I am in Abha with my family.","It is windy.","We eat corn.","Dear Layla,"],"dok":1,"skill":"message","stage":"controlled"}]},{"id":"RW-L01-U6-LS4-A2","type":"open","stage":"guided","instructions":"Guided practice: Write each line correctly. Add capitals and commas.","instructions_ar":"اكتب كل سطر بشكل صحيح بإضافة الحروف الكبيرة والفواصل.","items":[{"q":"dear omar","answer":"Dear Omar,","explanation":"Capitals + comma.","explanation_ar":"حروف كبيرة + فاصلة.","dok":1,"skill":"punctuation","stage":"guided"},{"q":"love noura","answer":"Love, / Noura","explanation":"Comma after Love; name on its own line.","explanation_ar":"فاصلة بعد Love والاسم في سطر.","dok":2,"skill":"punctuation","stage":"guided"},{"q":"dear grandpa saleh","answer":"Dear Grandpa Saleh,","explanation":"Capitals for each name word + comma.","explanation_ar":"حروف كبيرة + فاصلة.","dok":1,"skill":"punctuation","stage":"guided"},{"q":"your friend sami","answer":"Your friend, / Sami","explanation":"Comma after friend; name on its own line.","explanation_ar":"فاصلة بعد friend.","dok":2,"skill":"punctuation","stage":"guided"},{"q":"i am in jeddah","answer":"I am in Jeddah.","explanation":"Capital I and J; period.","explanation_ar":"I وJ كبيرتان ونقطة.","dok":1,"skill":"capitals","stage":"guided"},{"q":"here is hot","answer":"It is hot here.","explanation":"Use It is … here.","explanation_ar":"استخدم It is … here.","dok":2,"skill":"usage","stage":"guided"}]},{"id":"RW-L01-U6-LS4-A3","type":"open","stage":"freer","instructions":"Freer practice: Answer the three message questions for a trip to the sea.","instructions_ar":"أجب عن أسئلة الرسالة الثلاثة لرحلة إلى البحر.","items":[{"q":"Where are you?","answer":"I am at the Red Sea in Jeddah.","explanation":"I am in/at + place.","explanation_ar":"I am in/at + مكان.","dok":1,"skill":"message","stage":"freer"},{"q":"What is the weather like?","answer":"It is hot and sunny here.","explanation":"It is + weather.","explanation_ar":"It is + طقس.","dok":1,"skill":"message","stage":"freer"},{"q":"What do you do?","answer":"I swim and I play on the sand.","explanation":"Actions with and.","explanation_ar":"أفعال مع and.","dok":1,"skill":"message","stage":"freer"},{"q":"What do you wear?","answer":"I wear a hat.","explanation":"I wear + clothes.","explanation_ar":"I wear + ملابس.","dok":1,"skill":"message","stage":"freer"}]},{"id":"RW-L01-U6-LS4-A4","type":"open","stage":"production","instructions":"Writing: Write a short postcard to a friend.","instructions_ar":"اكتب بطاقة بريدية قصيرة لصديق.","items":[{"q":"Write the greeting.","answer":"Dear Badr,","explanation":"Dear + name + comma.","explanation_ar":"Dear + اسم + فاصلة.","dok":1,"skill":"postcard","stage":"production"},{"q":"Write two message sentences: where and weather.","answer":"I am in AlUla. It is cool and sunny here.","explanation":"Two sentences.","explanation_ar":"جملتان.","dok":2,"skill":"postcard","stage":"production"},{"q":"Write what you do or wear.","answer":"I visit old buildings and I wear a hat.","explanation":"One sentence.","explanation_ar":"جملة واحدة.","dok":2,"skill":"postcard","stage":"production"},{"q":"Write the closing and your name.","answer":"Your friend, / Ali","explanation":"Closing + comma + name.","explanation_ar":"خاتمة + فاصلة + اسم.","dok":1,"skill":"postcard","stage":"production"}]}],"game":{"name":"Postcard Puzzle","mechanic":"timed_quiz","rules":["On this screen: answer the lesson questions as fast as you can.","In class: Postcard builder: five strips appear; the child drags each to the right place on a postcard (address on the right). When correct, the postcard 'flies' to a map pin of a Saudi city.","Each pair gets an envelope with five strips and a blank postcard board.","On \"Go!\", they place the strips in the right places.","They read the postcard aloud.","First correct pair = 3 points; other correct pairs = 2 points.","Swap envelopes and play again."],"data":[]},"exit_quiz":[{"q":"A postcard is ___.","answer":"a short note with a picture that you send","explanation":"Postcards are short notes with pictures.","explanation_ar":"رسالة قصيرة بصورة.","options":["a long story book","a menu","a play","a short note with a picture that you send"],"dok":1,"skill":"genre"},{"q":"Which is a correct greeting?","answer":"Dear Omar,","explanation":"Capital letters + comma.","explanation_ar":"حروف كبيرة وفاصلة.","options":["Dear Omar.","dear omar","Dear Omar,","Omar dear,"],"dok":1,"skill":"punctuation"},{"q":"Which is a correct closing?","answer":"Love,","explanation":"Comma after Love.","explanation_ar":"فاصلة بعد Love.","options":["Love.","love","Love!","Love,"],"dok":1,"skill":"punctuation"},{"q":"What goes on the right side of a postcard?","answer":"the address","explanation":"The address goes on the right.","explanation_ar":"العنوان.","options":["the address","the greeting","the closing","the title"],"dok":1,"skill":"postcard parts"},{"q":"Which sentence tells what you WEAR?","answer":"I wear a hat.","explanation":"Wear + clothes.","explanation_ar":"ألبس قبعة.","options":["I wear a hat.","I am in Jeddah.","It is sunny.","Dear Badr,"],"dok":1,"skill":"message"},{"q":"Which sentence about the weather here is correct?","answer":"It is cool here.","explanation":"Use It is … here.","explanation_ar":"It is … here.","options":["Here is cool.","Is cool here.","It is cool here.","Cool is here."],"dok":2,"skill":"usage"},{"q":"*The mountains are green.* Where might Noura be?","answer":"in Abha","explanation":"Abha has green mountains.","explanation_ar":"في أبها.","options":["in the Red Sea","in Abha","in a kitchen","at a café"],"dok":2,"skill":"inference"},{"q":"Why does Noura write *See you soon!*?","answer":"to say she will meet Layla again","explanation":"It is a friendly last line.","explanation_ar":"لتقول إنها ستراها قريبًا.","options":["to tell the weather","to give an address","to say where she is","to say she will meet Layla again"],"dok":2,"skill":"author's purpose"},{"q":"What do you put on a postcard before you send it?","answer":"a stamp","explanation":"Mail needs a stamp.","explanation_ar":"طابع بريد.","options":["a spoon","a stamp","a coat","a map"],"dok":1,"skill":"vocabulary"},{"q":"Which message is the BEST for a postcard?","answer":"I am in AlUla. It is sunny. I see old rocks. See you soon!","explanation":"It tells where, weather and do.","explanation_ar":"تذكر المكان والطقس والنشاط.","options":["I am in AlUla. It is sunny. I see old rocks. See you soon!","AlUla.","It is.","Love, Love, Love."],"dok":3,"skill":"evaluate"}],"images":[{"id":"IMG-RW-L01-U6-LS4-V01","prompt":"Picture for the word 'postcard': a postcard with a mountain picture on the front"},{"id":"IMG-RW-L01-U6-LS4-V02","prompt":"Picture for the word 'address': the back of a postcard with lines for an address"},{"id":"IMG-RW-L01-U6-LS4-V03","prompt":"Picture for the word 'stamp': a colorful stamp with a falcon picture"},{"id":"IMG-RW-L01-U6-LS4-V04","prompt":"Picture for the word 'trip': a family car on a mountain road"},{"id":"IMG-RW-L01-U6-LS4-V05","prompt":"Picture for the word 'visit': a family knocking on a door with a gift"},{"id":"IMG-RW-L01-U6-LS4-V06","prompt":"Picture for the word 'cool': green mountains with light mist"},{"id":"IMG-RW-L01-U6-LS4-V07","prompt":"Picture for the word 'mountains': green mountains of Abha with clouds"},{"id":"IMG-RW-L01-U6-LS4-01","prompt":"A postcard picture of green mountains in Abha."},{"id":"IMG-RW-L01-U6-LS4-02","prompt":"The back of a postcard with message and address sides."},{"id":"IMG-RW-L01-U6-LS4-03","prompt":"Saqr carries a postcard over a map."}],"audio":[{"id":"AUD-RW-L01-U6-LS4-V01","script":"postcard. Noura sends a postcard."},{"id":"AUD-RW-L01-U6-LS4-V02","script":"address. Write the address on the right."},{"id":"AUD-RW-L01-U6-LS4-V03","script":"stamp. Put a stamp on the postcard."},{"id":"AUD-RW-L01-U6-LS4-V04","script":"trip. We go on a trip to Abha."},{"id":"AUD-RW-L01-U6-LS4-V05","script":"visit. We visit Grandma on Friday."},{"id":"AUD-RW-L01-U6-LS4-V06","script":"cool. Abha is cool in summer."},{"id":"AUD-RW-L01-U6-LS4-V07","script":"mountains. The mountains are green."},{"id":"AUD-RW-L01-U6-LS4-T1","script":"Dear Layla, I am in Abha with my family. It is cool and cloudy here. The mountains are green and beautiful! Today it is windy, so I wear my coat. We eat corn and drink hot milk. See you soon! Love, Noura *Address side: Layla Mansour, 12 Palm Street, Taif*"},{"id":"AUD-RW-L01-U6-LS4-VID","script":"Noura is on a trip to Abha! She writes a postcard to Layla. First, the greeting: Dear Layla, – with a comma! The message: Where? I am in Abha. Weather? It is cool and cloudy. What do I do? I wear my coat. We eat corn. The closing: Love, – comma! – and my name: Noura. The address goes on the right. Then add a stamp! Greeting, message, closing, name, address. Now write your postcard!"}]},{"id":"RW-L01-U6-LS5","title":"Writing Workshop: A weather postcard to a friend","lesson_type":"writing_workshop","objectives":["plan a postcard from a real or imagined trip: place, weather, clothes and activities","write a postcard with a greeting, 4 message sentences, a closing and a name","edit capitals and commas, draw the postcard front and 'send' it to a classmate"],"objectives_ar":["التخطيط لبطاقة بريدية من رحلة حقيقية أو متخيلة: المكان والطقس والملابس والأنشطة.","كتابة بطاقة بريدية بتحية و4 جمل وخاتمة واسم.","تدقيق الحروف الكبيرة والفواصل، ورسم وجه البطاقة وإرسالها إلى زميل."],"success_criteria":["I can plan my postcard.","I can write a postcard with all its parts.","I can check commas and capitals and send it."],"success_criteria_ar":["أستطيع التخطيط لبطاقتي.","أستطيع كتابة بطاقة بريدية بكل أجزائها.","أستطيع مراجعة الفواصل والحروف الكبيرة وإرسالها."],"map_area":"Language Usage: Write, Revise Texts for Purpose and Audience (cross-strand)","vocabulary":[{"word":"send","pos":"verb","ipa":"/sɛnd/","definition":"to make something go to another person","arabic":"يرسل","example":"I send a postcard to my friend.","image_id":"IMG-RW-L01-U6-LS5-V01","audio_id":"AUD-RW-L01-U6-LS5-V01","tier":"core"},{"word":"vacation","pos":"noun","ipa":"/veɪˈkeɪʃən/","definition":"days with no school or work, often on a trip","arabic":"إجازة","example":"We go to Abha on vacation.","image_id":"IMG-RW-L01-U6-LS5-V02","audio_id":"AUD-RW-L01-U6-LS5-V02","tier":"core"},{"word":"beach","pos":"noun","ipa":"/bitʃ/","definition":"the sandy land next to the sea","arabic":"شاطئ","example":"We play on the beach.","image_id":"IMG-RW-L01-U6-LS5-V03","audio_id":"AUD-RW-L01-U6-LS5-V03","tier":"core"},{"word":"hat","pos":"noun","ipa":"/hæt/","definition":"you wear it on your head","arabic":"قبعة","example":"Wear a hat in the sun.","image_id":"IMG-RW-L01-U6-LS5-V04","audio_id":"AUD-RW-L01-U6-LS5-V04","tier":"core"},{"word":"sunglasses","pos":"noun","ipa":"/ˈsʌnˌɡlæsɪz/","definition":"dark glasses for the sun","arabic":"نظارة شمسية","example":"My sunglasses are black.","image_id":"IMG-RW-L01-U6-LS5-V05","audio_id":"AUD-RW-L01-U6-LS5-V05","tier":"core"},{"word":"scarf","pos":"noun","ipa":"/skɑrf/","definition":"a long piece of cloth for your neck","arabic":"وشاح","example":"Wear a scarf in winter.","image_id":"IMG-RW-L01-U6-LS5-V06","audio_id":"AUD-RW-L01-U6-LS5-V06","tier":"core"},{"word":"soon","pos":"adverb","ipa":"/sun/","definition":"in a short time","arabic":"قريبًا","example":"See you soon!","image_id":"IMG-RW-L01-U6-LS5-V07","audio_id":"AUD-RW-L01-U6-LS5-V07","tier":"core"}],"explanation":{"text":"Today you write a **postcard** from a trip. It can be real or imagined.\n\nPlan four ideas: **Where** am I? **What is the weather?** **What do I wear?** **What do I do?** Then write one sentence for each.\n\nUse what you learned: **capital letters** for names and places, **commas** after the greeting and closing, **and** to join two things, and **describing words**.","examples":["Greeting: **Dear Adam,**","Where: **I am at the beach in Jeddah.**","Weather: **It is hot and sunny here.**","Wear: **I wear a hat and sunglasses.**","Do: **I swim and I play on the sand.**","Where (winter): **I am in Taif with Grandpa Saleh.**","Weather (winter): **It is cold and rainy today.**","Wear (winter): **I wear my coat and a scarf.**","Closing: **See you soon! Your friend, Sami**"],"common_errors":["✗ I am in the beach. → ✓ I am at the beach. (Say **at the beach**.)","✗ I wear a sunglasses. → ✓ I wear sunglasses. (No **a** with sunglasses.)","✗ It is hot and sunny here, I swim. → ✓ It is hot and sunny here. I swim. (Two sentences need a period.)","✗ Dear adam → ✓ Dear Adam, (Capital A and a comma.)","✗ I go to vacation. → ✓ I go on vacation. (Say **on vacation**.)","✗ See you soon (no !) → ✓ See you soon! (End with an exclamation mark or a period.)"],"arabic":"اليوم تكتب بطاقة بريدية من رحلة حقيقية أو متخيلة.\n\nخطط لأربع أفكار: أين أنا؟ كيف الطقس؟ ماذا ألبس؟ ماذا أفعل؟ ثم اكتب جملة لكل فكرة.\n\nاستخدم ما تعلمته: الحروف الكبيرة للأسماء والأماكن، والفاصلة بعد التحية والخاتمة، وand للربط، والكلمات الوصفية.\n\nانتبه: نقول at the beach وon vacation."},"video":{"script":[{"time":"00:00–00:15","narration":"Sami is on vacation in Jeddah. He wants to send a postcard to Adam!","on_screen":"My Weather Postcard","visual":"Sami on a sunny beach with a hat, holding a blank postcard."},{"time":"00:15–00:45","narration":"Plan: Where? Jeddah. Weather? Hot and sunny. Wear? A hat and sunglasses. Do? Swim!","on_screen":"1 Plan – Where · Weather · Wear · Do","visual":"Four bubbles fill with icons: map pin, sun, hat, swimmer."},{"time":"00:45–01:20","narration":"Draft: Dear Adam, I am at the beach in Jeddah. It is hot and sunny here. I wear a hat and sunglasses. I swim and I play on the sand. See you soon! Your friend, Sami","on_screen":"2 Draft","visual":"Sami writes; each sentence matches a bubble."},{"time":"01:20–01:45","narration":"Revise: add a describing word. I swim in the BLUE sea!","on_screen":"3 Revise ➕ blue","visual":"The word 'blue' slides in; the sea sparkles."},{"time":"01:45–02:10","narration":"Edit: Dear Adam – comma! Jeddah – capital J! Your friend – comma!","on_screen":"4 Edit ✔","visual":"Commas and capitals glow."},{"time":"02:10–02:40","narration":"Publish: draw the front and send it to a friend in class!","on_screen":"5 Send ✉️","visual":"Sami drops the postcard in a class mailbox; Adam opens it and smiles."}],"captions_ar":["سامي في إجازة في جدة، ويريد أن يرسل بطاقة بريدية إلى آدم!","خطِّط: أين؟ جدة. الطقس؟ حار ومشمس. ماذا ألبس؟ قبعة ونظارة شمسية. ماذا أفعل؟ أسبح!","المسودة: عزيزي آدم، أنا على الشاطئ في جدة. الجو حار ومشمس هنا. ألبس قبعة ونظارة شمسية. أسبح وألعب على الرمل. أراك قريبًا! صديقك سامي.","التحسين: أضف كلمة وصفية: أسبح في البحر الأزرق!","التدقيق: فاصلة بعد Dear Adam، وحرف J كبير في Jeddah، وفاصلة بعد Your friend.","النشر: ارسم وجه البطاقة وأرسلها إلى صديق في الفصل!"],"voice":"Narrator: American English, warm female teacher, speed 0.8. Sami: cheerful boy on the beach. Sea sounds softly."},"texts":[],"activities":[{"id":"RW-L01-U6-LS5-A1","type":"mcq","stage":"controlled","instructions":"Controlled practice: Choose the best answer.","instructions_ar":"اختر أفضل إجابة.","items":[{"q":"On a sunny beach day, you wear ___.","answer":"a hat and sunglasses","explanation":"Sun = hat and sunglasses.","explanation_ar":"قبعة ونظارة شمسية.","options":["a coat and a scarf","boots and a coat","an umbrella","a hat and sunglasses"],"dok":1,"skill":"vocabulary","stage":"controlled"},{"q":"On a cold windy day, you wear ___.","answer":"a coat and a scarf","explanation":"Cold = coat and scarf.","explanation_ar":"معطف ووشاح.","options":["sunglasses","a sun hat only","a coat and a scarf","nothing"],"dok":1,"skill":"vocabulary","stage":"controlled"},{"q":"Days with no school, often on a trip, are a ___.","answer":"vacation","explanation":"Vacation = no school.","explanation_ar":"إجازة.","options":["beach","stamp","vacation","season"],"dok":1,"skill":"vocabulary","stage":"controlled"},{"q":"The sandy land next to the sea is the ___.","answer":"beach","explanation":"Beach = sand by the sea.","explanation_ar":"الشاطئ.","options":["beach","mountain","kitchen","desert"],"dok":1,"skill":"vocabulary","stage":"controlled"},{"q":"Which phrase about the beach is correct?","answer":"at the beach","explanation":"We say at the beach.","explanation_ar":"at the beach.","options":["in the beach","at the beach","on the beach sea","the beach at"],"dok":2,"skill":"usage","stage":"controlled"},{"q":"Which line ends a postcard in a friendly way?","answer":"See you soon!","explanation":"A friendly last line.","explanation_ar":"سطر ودي للنهاية.","options":["Dear Adam,","See you soon!","I am in Jeddah.","It is hot."],"dok":1,"skill":"postcard parts","stage":"controlled"}]},{"id":"RW-L01-U6-LS5-A2","type":"sequence","stage":"guided","instructions":"Put in order: Put the postcard lines in order.","instructions_ar":"رتّب أسطر البطاقة.","items":[{"q":"Order Reem's postcard to Huda.","answer":"Dear Huda, → I am in Abha. → It is cool here. → Love, Reem","explanation":"Greeting → message → closing.","explanation_ar":"تحية ← رسالة ← خاتمة.","stage":"guided","parts":["Dear Huda,","It is cool here.","Love, Reem","I am in Abha."],"target":["Dear Huda,","I am in Abha.","It is cool here.","Love, Reem"]},{"q":"Order Faris's postcard to Grandpa.","answer":"Dear Grandpa, → I am at the beach. → I swim every day. → Your friend, Faris","explanation":"Greeting first; closing last.","explanation_ar":"التحية أولًا والخاتمة أخيرًا.","stage":"guided","parts":["I am at the beach.","Dear Grandpa,","Your friend, Faris","I swim every day."],"target":["Dear Grandpa,","I am at the beach.","I swim every day.","Your friend, Faris"]},{"q":"Build a weather sentence for a beach postcard.","answer":"It is hot and sunny here.","explanation":"It is hot and sunny here.","explanation_ar":"الجو حار ومشمس هنا.","stage":"guided","parts":["hot","here.","is","and","sunny","It"],"target":["It","is","hot","and","sunny","here."]},{"q":"Build a 'wear' sentence for a cold day.","answer":"I wear a coat and a scarf.","explanation":"I wear a coat and a scarf.","explanation_ar":"ألبس معطفًا ووشاحًا.","stage":"guided","parts":["wear","a","and","a","coat","scarf.","I"],"target":["I","wear","a","coat","and","a","scarf."]},{"q":"Build a sentence about a summer vacation.","answer":"We go on vacation in summer.","explanation":"on vacation.","explanation_ar":"في إجازة.","stage":"guided","parts":["vacation","summer.","go","We","on","in"],"target":["We","go","on","vacation","in","summer."]},{"q":"Build the friendly last line.","answer":"See you soon!","explanation":"See you soon!","explanation_ar":"أراك قريبًا!","stage":"guided","parts":["soon!","See","you"],"target":["See","you","soon!"]}]},{"id":"RW-L01-U6-LS5-A3","type":"organizer","stage":"freer","instructions":"Organizer: Plan your postcard. Fill in the four bubbles.","instructions_ar":"خطط لبطاقتك بملء الفقاعات الأربع.","items":[{"q":"Where am I?","answer":"in Taif with my family","explanation":"A place.","explanation_ar":"مكان.","dok":1,"skill":"planning","stage":"freer"},{"q":"What is the weather?","answer":"cold and rainy","explanation":"Weather words.","explanation_ar":"كلمات طقس.","dok":1,"skill":"planning","stage":"freer"},{"q":"What do I wear?","answer":"my coat and a scarf","explanation":"Clothes.","explanation_ar":"ملابس.","dok":1,"skill":"planning","stage":"freer"},{"q":"What do I do?","answer":"visit Grandpa and drink hot milk","explanation":"Actions.","explanation_ar":"أفعال.","dok":1,"skill":"planning","stage":"freer"}]},{"id":"RW-L01-U6-LS5-A4","type":"writing","stage":"production","instructions":"Writing: Write your postcard. Then edit and send it.","instructions_ar":"اكتب بطاقتك ثم دققها وأرسلها.","items":[{"q":"Write your greeting and your 'where' sentence.","answer":"Dear Noura, I am in Taif with my family.","explanation":"Greeting + sentence.","explanation_ar":"تحية + جملة.","dok":1,"skill":"writing","stage":"production"},{"q":"Write your weather and wear sentences.","answer":"It is cold and rainy here. I wear my coat and a scarf.","explanation":"Two sentences.","explanation_ar":"جملتان.","dok":2,"skill":"writing","stage":"production"},{"q":"Write your 'do' sentence and a friendly last line.","answer":"I drink hot milk with Grandpa. See you soon!","explanation":"Sentence + last line.","explanation_ar":"جملة + سطر ختامي.","dok":2,"skill":"writing","stage":"production"},{"q":"Write your closing and your name.","answer":"Love, Lama","explanation":"Closing + comma + name.","explanation_ar":"خاتمة + فاصلة + اسم.","dok":1,"skill":"writing","stage":"production","_w":{"checklist":[],"min":null,"max":null}}]},{"id":"RW-L01-U6-LS5-ORG","type":"organizer","organizer":"Four-Bubble Postcard Plan","instructions":"Organizer: Write one idea in each bubble.","items":[{"q":"Where am I?","answer":"at the beach in Jeddah"},{"q":"What is the weather?","answer":"hot and sunny"},{"q":"What do I wear?","answer":"a hat and sunglasses"},{"q":"What do I do?","answer":"swim and play on the sand"}]},{"id":"RW-L01-U6-LS5-WR","type":"writing","instructions":"Writing: Write a postcard to a friend from a trip. Write a greeting, 4 sentences about the place and the weather, a closing and your name. Write a postcard to a friend from a trip. Write a greeting, 4 sentences about the place and the weather, a closing and your name.","instructions_ar":"اكتب بطاقة بريدية لصديق من رحلة: تحية، و4 جمل عن المكان والطقس، وخاتمة، واسمك.","prompt":"Write a postcard to a friend from a trip. Write a greeting, 4 sentences about the place and the weather, a closing and your name.","checklist":["I wrote a greeting with a comma.","I wrote where I am and what the weather is like.","I wrote what I wear and what I do.","I used and and one describing word.","Names and places start with capital letters.","I wrote a closing with a comma and my name."],"rubric_id":"RW-RUBRIC-5T","min_words":20,"max_words":60,"organizer":"Four-Bubble Postcard Plan (where – weather – wear – do)","items":[{"q":"Write a postcard to a friend from a trip. Write a greeting, 4 sentences about the place and the weather, a closing and your name.","answer":"Dear Adam, I am at the beach in Jeddah. It is hot and sunny here. I wear a hat and sunglasses. I swim in the blue sea and I play on the sand. See you soon! Your friend, Sami","_w":{"checklist":["I wrote a greeting with a comma.","I wrote where I am and what the weather is like.","I wrote what I wear and what I do.","I used and and one describing word.","Names and places start with capital letters.","I wrote a closing with a comma and my name."],"min":20,"max":60}}]}],"game":{"name":"Pack for the Weather","mechanic":"timed_quiz","rules":["On this screen: answer the lesson questions as fast as you can.","In class: Suitcase packer: a postcard with a weather line appears; the child drags the right clothes into a suitcase. When it is right, the suitcase closes and flies to the city on a map.","A student picks a weather postcard and reads it aloud (\"It is cold and windy in Abha.\").","The team chooses two clothes cards for the suitcase.","They say: \"I wear a coat and a scarf.\"","Correct choice = 2 points.","Teams take turns with 8 postcards."],"data":[]},"exit_quiz":[{"q":"What comes FIRST on a postcard?","answer":"the greeting","explanation":"Greetings start postcards.","explanation_ar":"التحية أولًا.","options":["the closing","the name","the greeting","the stamp"],"dok":1,"skill":"postcard parts"},{"q":"Which is a weather sentence?","answer":"It is cold and rainy here.","explanation":"Cold and rainy are weather words.","explanation_ar":"كلمات طقس.","options":["It is cold and rainy here.","I am in Taif.","Love, Lama","Dear Noura,"],"dok":1,"skill":"message"},{"q":"Which phrase is correct for a trip?","answer":"on vacation","explanation":"We say on vacation.","explanation_ar":"on vacation.","options":["in vacation","at vacation","to vacation","on vacation"],"dok":2,"skill":"usage"},{"q":"You are in the sun at the beach. What do you wear?","answer":"a hat","explanation":"Hats protect from the sun.","explanation_ar":"قبعة.","options":["a scarf","a coat","boots","a hat"],"dok":1,"skill":"vocabulary"},{"q":"*See you soon!* *Soon* means ___.","answer":"in a short time","explanation":"Soon = in a short time.","explanation_ar":"قريبًا.","options":["never","a long time ago","in a short time","at night"],"dok":1,"skill":"vocabulary"},{"q":"Which closing is written correctly?","answer":"Your friend,","explanation":"Capital Y and a comma.","explanation_ar":"Y كبيرة وفاصلة.","options":["Your friend,","your friend","Your friend.","Your, friend"],"dok":1,"skill":"punctuation"},{"q":"Which sentence uses *and* to join two clothes?","answer":"I wear a coat and a scarf.","explanation":"Coat and scarf are joined.","explanation_ar":"and تربط ملبسين.","options":["I wear a coat.","I wear a coat and a scarf.","It is cold.","Dear Omar,"],"dok":2,"skill":"joining words"},{"q":"Fix: *I am in the beach.*","answer":"I am at the beach.","explanation":"Say at the beach.","explanation_ar":"at the beach.","options":["I am on beach.","I am at the beach.","I am beach.","I in the beach."],"dok":2,"skill":"editing"},{"q":"A postcard says *It is cool and the mountains are green.* Which city might it be from?","answer":"Abha","explanation":"Abha has cool green mountains.","explanation_ar":"أبها.","options":["Abha","Riyadh in summer","the Red Sea","the Empty Quarter"],"dok":3,"skill":"inference"},{"q":"Which postcard message is the most complete?","answer":"I am in Jeddah. It is hot. I wear a hat. I swim.","explanation":"It tells where, weather, wear and do.","explanation_ar":"تذكر المكان والطقس والملبس والنشاط.","options":["I am in Jeddah.","I am in Jeddah. It is hot. I wear a hat. I swim.","Hot.","Love, Love."],"dok":3,"skill":"evaluate"}],"images":[{"id":"IMG-RW-L01-U6-LS5-V01","prompt":"Picture for the word 'send': a hand putting a postcard into a red mailbox"},{"id":"IMG-RW-L01-U6-LS5-V02","prompt":"Picture for the word 'vacation': a family with suitcases at the airport"},{"id":"IMG-RW-L01-U6-LS5-V03","prompt":"Picture for the word 'beach': a sandy beach with gentle waves"},{"id":"IMG-RW-L01-U6-LS5-V04","prompt":"Picture for the word 'hat': a sun hat"},{"id":"IMG-RW-L01-U6-LS5-V05","prompt":"Picture for the word 'sunglasses': black sunglasses"},{"id":"IMG-RW-L01-U6-LS5-V06","prompt":"Picture for the word 'scarf': a warm red scarf"},{"id":"IMG-RW-L01-U6-LS5-V07","prompt":"Picture for the word 'soon': a clock with a small arrow moving a little"},{"id":"IMG-RW-L01-U6-LS5-01","prompt":"Students post postcards in a class mailbox."},{"id":"IMG-RW-L01-U6-LS5-02","prompt":"Sami on the beach in a hat and sunglasses."},{"id":"IMG-RW-L01-U6-LS5-03","prompt":"A plan with four bubbles for place, weather, clothes and activity."}],"audio":[{"id":"AUD-RW-L01-U6-LS5-V01","script":"send. I send a postcard to my friend."},{"id":"AUD-RW-L01-U6-LS5-V02","script":"vacation. We go to Abha on vacation."},{"id":"AUD-RW-L01-U6-LS5-V03","script":"beach. We play on the beach."},{"id":"AUD-RW-L01-U6-LS5-V04","script":"hat. Wear a hat in the sun."},{"id":"AUD-RW-L01-U6-LS5-V05","script":"sunglasses. My sunglasses are black."},{"id":"AUD-RW-L01-U6-LS5-V06","script":"scarf. Wear a scarf in winter."},{"id":"AUD-RW-L01-U6-LS5-V07","script":"soon. See you soon!"},{"id":"AUD-RW-L01-U6-LS5-VID","script":"Sami is on vacation in Jeddah. He wants to send a postcard to Adam! Plan: Where? Jeddah. Weather? Hot and sunny. Wear? A hat and sunglasses. Do? Swim! Draft: Dear Adam, I am at the beach in Jeddah. It is hot and sunny here. I wear a hat and sunglasses. I swim and I play on the sand. See you soon! Your friend, Sami Revise: add a describing word. I swim in the BLUE sea! Edit: Dear Adam – comma! Jeddah – capital J! Your friend – comma! Publish: draw the front and send it to a friend in class!"}]}],"unit_test":[{"q":"Gray shapes in the sky are ___.","answer":"clouds","explanation":"Clouds are in the sky.","explanation_ar":"السحب.","options":["coats","hats","beaches","clouds"],"dok":1,"skill":"vocabulary","_part":"Part A – Words"},{"q":"It is very cold. Wear your ___.","answer":"coat","explanation":"A coat keeps you warm.","explanation_ar":"المعطف.","options":["sunglasses","umbrella","sun","coat"],"dok":1,"skill":"vocabulary","_part":"Part A – Words"},{"q":"A day with a lot of wind is ___.","answer":"windy","explanation":"Wind + y.","explanation_ar":"عاصف.","options":["windy","sunny","rainy","hot"],"dok":1,"skill":"word families","_part":"Part A – Words"},{"q":"The coldest season is ___.","answer":"winter","explanation":"Winter is the coldest.","explanation_ar":"الشتاء.","options":["summer","vacation","winter","weather"],"dok":1,"skill":"vocabulary","_part":"Part A – Words"},{"q":"We need an ___ on a rainy day.","answer":"umbrella","explanation":"Umbrellas keep you dry.","explanation_ar":"مظلة.","options":["umbrella","sun","hat","beach"],"dok":1,"skill":"vocabulary","_part":"Part A – Words"},{"q":"Summer and winter are ___.","answer":"seasons","explanation":"They are seasons.","explanation_ar":"فصول.","options":["clouds","seasons","coats","maps"],"dok":1,"skill":"vocabulary","_part":"Part A – Words"},{"q":"Faris has no school this week. He is on ___.","answer":"vacation","explanation":"No school = vacation.","explanation_ar":"إجازة.","options":["beach","vacation","weather","cloud"],"dok":2,"skill":"vocabulary in context","_part":"Part A – Words"},{"q":"The ground has no water. It is very ___.","answer":"dry","explanation":"No water = dry.","explanation_ar":"جاف.","options":["rainy","cool","dry","windy"],"dok":2,"skill":"vocabulary in context","_part":"Part A – Words"},{"q":"Which greeting is written correctly?","answer":"Dear Faris,","explanation":"Capitals + comma.","explanation_ar":"حروف كبيرة وفاصلة.","options":["dear faris","Dear Faris,","Dear Faris.","Faris dear,"],"dok":1,"skill":"punctuation","_part":"Part D – Check the sentences"},{"q":"Which sentence has quotation marks in the right place?","answer":"\"It is raining!\" says Lama.","explanation":"Only the spoken words go inside.","explanation_ar":"الكلام المنقول فقط داخل العلامتين.","options":["\"It is raining!\" says Lama.","\"It is raining! says Lama.\"","It is \"raining!\" says Lama.","\"It is\" raining! says Lama."],"dok":2,"skill":"punctuation","_part":"Part D – Check the sentences"},{"q":"Which spelling is correct for a day with a lot of sun?","answer":"sunny","explanation":"sun + n + y.","explanation_ar":"sunny.","options":["sunly","suny","suns","sunny"],"dok":1,"skill":"spelling","_part":"Part D – Check the sentences"},{"q":"A text is called *Meet Ms. Hala, the Pilot*. What is the main topic?","answer":"Ms. Hala's job as a pilot","explanation":"The title tells the topic.","explanation_ar":"عمل هالة كطيارة.","options":["airplanes are big","the sky is blue","Ms. Hala's job as a pilot","pilots wear hats"],"dok":2,"skill":"main topic","_part":"Part D – Check the sentences"},{"q":"Which sentence about today's weather is correct?","answer":"It is cold here today.","explanation":"It is … here.","explanation_ar":"It is … here.","options":["Here is cold today.","It is cold here today.","Is cold here today.","Cold here is today."],"dok":2,"skill":"usage","_part":"Part D – Check the sentences"}],"unit_writing":{"task":"What is your favorite weather? Write 3–4 sentences: what it is like, what you wear and what you do.","model":"My favorite weather is rainy weather. It is cool and the sky is gray. I wear my coat and I take my umbrella. I play outside with my sister.","marks":20}});
